      dmg:(w)=>{
        const gl = gwepEffLv(DB.gweps.blade.lv||1);
        const g = 3 + gl*1.8;
        const tier = gl>=30?1.4 : gl>=15?1.2 : 1;
        return g * [1,1.25,1.55,1.9,2.3][w.lv-1] * tier * (w.evolved?1.5:1);
      },
