        if (ph===3){ showBossBanner('3페이즈 — 새벽 3시', '어둠 속 — 소리가 나는 곳이 곧 위험이다.', '#b8362e'); screenDimT=Math.max(screenDimT,0.6); SFX.play('warn'); }
