      if (b.wTrX===undefined){ b.wTrX=player.x; b.wTrY=player.y; b.wTrA=Math.random()*Math.PI*2; }
      b.wTrA += (Math.random()-0.5)*dt*1.8;
      b.wTrX += Math.cos(b.wTrA)*30*dt; b.wTrY += Math.sin(b.wTrA)*30*dt;
      const trR = ph===1?120 : ph===2?95 : 75;
