  //  🔴 v6.205 **보스 팔레트** — 보스만 옛 통짜 차콜이었다(`o.ink`가 bodyTone을 덮어 악센트 혼합이 죽는다).
  //   화풍은 플레이어와 같은 도트 5톤(o.pal 경로), **색은 보스 악센트**(HANDOFF 사용자 결정 —
  //   컬러 해금은 캐릭터까지, 보스는 무채색 + 악센트). 그림자는 차갑게·하이라이트는 따뜻하게(v6.193 색조 이동).
  //   ⚠ 피부는 무채색 창백으로 둔다 — 얼굴에 색이 돌면 '컬러 해금'을 넘는다.
  const BOSS_PAL_CACHE = {};
  function bossPal(key, emp){
    const ck = key + (emp ? '!' : '');
    if (BOSS_PAL_CACHE[ck]) return BOSS_PAL_CACHE[ck];
    const acc = BOSS_ACCENTS[key] || '#b8362e';
    const dk = (hex, amt)=> mixHex(hex, '#241a45', amt);
    const lt = (hex, amt)=> mixHex(hex, '#fff2c8', amt);
    //  몸통이 악센트를 머금는다 — 잡몹(무채색 덩어리)과 실루엣 색부터 갈린다. 분노(emp)는 한 단 어둡게.
    const cloth = emp ? dk(mixHex('#4a4650', acc, 0.42), 0.24) : mixHex('#4a4650', acc, 0.42);
    const p = {
      out: dk(acc, 0.84),
      hairM: dk(mixHex('#565863', acc, 0.20), 0.30),
      skinM: '#b6b3ae',
      clothM: cloth,
      leaM: dk(mixHex('#6a5f50', acc, 0.14), 0.20),
      metM: lt(mixHex('#aab0bc', acc, 0.22), 0.18),
    };
    BOSS_PAL_CACHE[ck] = p; return p;
  }
  function drawBoss(b){
    const t = performance.now()/1000;
    const face = player.x > b.x ? 1 : -1;
    const ink = PAL.ink, ink2 = PAL.ink2, mid = PAL.mid;
    // v6.47 보스 위압 연출: 피격 플래시 추적 + 바닥 위압 링 + 페이즈 핍 + 빈사 균열 (비주얼 대개편)
    if (b._phk===undefined) b._phk = b.hp;
    if (b.hp < b._phk - 1) b._fT = performance.now();
    b._phk = b.hp;
    if (!b.ghost){
      const ac0 = BOSS_ACCENTS[b.key] || '#b8362e';
      const bfrac = Math.max(0, b.hp/(b.maxHp||b.hp||1));
      ctx.save();
      ctx.strokeStyle = ac0;
      ctx.globalAlpha = 0.16 + 0.08*Math.sin(performance.now()/260);
      ctx.lineWidth = 2.4;
      ctx.beginPath(); ctx.ellipse(b.x, b.y + b.r*0.9, b.r*1.7 + Math.sin(performance.now()/260)*3, b.r*0.55, 0, 0, Math.PI*2); ctx.stroke();
      // 페이즈 핍 (체력 1/3 구간)
      for (let k=0;k<3;k++){
        ctx.globalAlpha = 0.85;
        ctx.fillStyle = bfrac > (2-k)/3 ? ac0 : 'rgba(120,120,120,0.35)';
        ctx.beginPath(); ctx.arc(b.x - 14 + k*14, b.y - b.r - 26, 3, 0, Math.PI*2); ctx.fill();
      }
      // v6.60 페이즈 전환 연출: 핍이 꺼지는 순간 악센트 충격파 + 방사광 + 흔들림
      const pipN = Math.ceil(bfrac*3);
      if (b._pipPrev!==undefined && pipN < b._pipPrev){
        effects.push({ type:'ring', x:b.x, y:b.y, life:0.5, age:0, r0:b.r*0.6, r1:b.r*3, col:ac0 });
        effects.push({ type:'rays', x:b.x, y:b.y, life:0.5, age:0, col:ac0 });
        shake = Math.min(14, shake+6);
        // v6.68 페이즈 전환 연출 컷: 짧은 정지 + 암전 — "국면이 바뀐다"
        freeze = Math.max(freeze, 0.5);
        screenDimT = Math.max(screenDimT, 0.6);
      }
      b._pipPrev = pipN;
      // 빈사(25% 미만): 붉은 균열 파편
      if (bfrac < 0.25){
        ctx.globalAlpha = 0.25 + 0.15*Math.sin(performance.now()/90);
        ctx.strokeStyle = '#c9403a'; ctx.lineWidth = 2;
        for (let k=0;k<4;k++){
          const ca = k*Math.PI/2 + performance.now()/800;
          ctx.beginPath();
          ctx.moveTo(b.x + Math.cos(ca)*b.r*0.5, b.y + Math.sin(ca)*b.r*0.5);
          ctx.lineTo(b.x + Math.cos(ca+0.35)*b.r*1.25, b.y + Math.sin(ca+0.35)*b.r*1.25);
          ctx.stroke();
        }
      }
      ctx.restore();
    }
    // v6.63 발악(분노) 순간 연출: enraged가 켜지는 프레임에 붉은 충격파 + 방사광 + 정지감
    if (!b.ghost){
      if (b.enraged && !b._enrFx){
        b._enrFx = true;
        effects.push({ type:'ring', x:b.x, y:b.y, life:0.55, age:0, r0:b.r*0.5, r1:b.r*3.4, col:'#c9403a' });
        effects.push({ type:'rays', x:b.x, y:b.y, life:0.55, age:0, col:'#c9403a' });
        shake = Math.min(16, shake+8);
        freeze = Math.max(freeze, 0.22);
      }
    }
    // v6.68 오라 정리: 몸 주위 이중 링 제거 — 바닥 그라운드 링(후단)과 분노 펄스만 남겨 위엄을 살린다

    // 돌진 텔레그래프
    if ((b.kind==='charger'||b.kind==='root') && b.chargeState==='telegraph'){
      const len = Math.max(W,H)*1.3;
      const ang = Math.atan2(b.chargeDir.y, b.chargeDir.x);
      ctx.save();
      ctx.translate(b.x,b.y);
      ctx.rotate(ang);
      const pulse = 0.28 + 0.2*Math.sin(performance.now()/55);
      ctx.fillStyle = MAP.key==='abyss' ? 'rgba(255,255,255,'+pulse.toFixed(2)+')' : 'rgba(0,0,0,'+pulse.toFixed(2)+')';
      ctx.fillRect(0, -b.r*0.9, len, b.r*1.8);
      ctx.restore();
    }
    // 빔 (이민기)
    if (b.kind==='beam' && (b.beamState==='warm'||b.beamState==='fire')){
      const len = 300;
      ctx.save();
      ctx.translate(b.x,b.y);
      ctx.rotate(b.beamA);
      if (b.beamState==='warm'){
        ctx.strokeStyle = MAP.key==='abyss' ? 'rgba(255,255,255,0.4)' : 'rgba(0,0,0,0.35)';
        ctx.setLineDash([8,6]);
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(len,0); ctx.stroke();
        ctx.setLineDash([]);
      } else {
        ctx.fillStyle = MAP.key==='abyss' ? 'rgba(255,255,255,0.7)' : 'rgba(0,0,0,0.65)';
        ctx.fillRect(0,-7,len,14);
        ctx.fillStyle = MAP.key==='abyss' ? 'rgba(255,255,255,0.3)' : 'rgba(0,0,0,0.25)';
        ctx.fillRect(0,-12,len,24);
      }
      ctx.restore();
    }

    ctx.save();
    if (b.ghost) ctx.globalAlpha = 0.22;
    if (b._fT && performance.now() - b._fT < 60) ctx.filter = 'brightness(1.8)'; // v6.47 피격 플래시
    if (b.kind!=='centipede') drawShadow(b.x, b.y + b.r*0.85, b.r*0.95);

    if (b.kind==='centipede'){
      // 고독근 — 소울풍 지네
      for (let i=b.segs.length-1;i>=0;i--){
        const s = b.segs[i];
        const rr = 13 - i*0.5;
        ctx.fillStyle = i%2===0 ? ink2 : ink;
        ctx.globalAlpha = (b.ghost?0.22:1) * (0.55 + 0.45*(1-i/b.segs.length));
        ctx.beginPath(); ctx.arc(s.x, s.y, Math.max(6,rr), 0, Math.PI*2); ctx.fill();
        if (i%2===0){
          ctx.strokeStyle = ink;
          ctx.lineWidth = 1.2;
          const la = Math.atan2(s.y-(b.segs[i-1]?b.segs[i-1].y:b.y), s.x-(b.segs[i-1]?b.segs[i-1].x:b.x)) + Math.PI/2;
          ctx.beginPath();
          ctx.moveTo(s.x+Math.cos(la)*rr, s.y+Math.sin(la)*rr);
          ctx.lineTo(s.x+Math.cos(la)*(rr+7), s.y+Math.sin(la)*(rr+7));
          ctx.moveTo(s.x-Math.cos(la)*rr, s.y-Math.sin(la)*rr);
          ctx.lineTo(s.x-Math.cos(la)*(rr+7), s.y-Math.sin(la)*(rr+7));
          ctx.stroke();
        }
      }
      ctx.globalAlpha = b.ghost?0.22:1;
      ctx.fillStyle = ink;
      ctx.beginPath(); ctx.arc(b.x, b.y, 16, 0, Math.PI*2); ctx.fill();
      const ha = Math.atan2(player.y-b.y, player.x-b.x);
      ctx.strokeStyle = ink;
      ctx.lineWidth = 2.4;
      ctx.beginPath(); ctx.arc(b.x+Math.cos(ha-0.5)*16, b.y+Math.sin(ha-0.5)*16, 7, ha-1.6, ha+0.5); ctx.stroke();
      ctx.beginPath(); ctx.arc(b.x+Math.cos(ha+0.5)*16, b.y+Math.sin(ha+0.5)*16, 7, ha-0.5, ha+1.6); ctx.stroke();
      ctx.fillStyle = MAP.key==='abyss' ? '#232427' : '#f6f6f4';
      ctx.beginPath();
      ctx.arc(b.x+Math.cos(ha-0.4)*9, b.y+Math.sin(ha-0.4)*9, 2.2, 0, Math.PI*2);
      ctx.arc(b.x+Math.cos(ha+0.4)*9, b.y+Math.sin(ha+0.4)*9, 2.2, 0, Math.PI*2);
      ctx.fill();

    } else if (b.kind==='meteor'){
      // 우주별 — 별 모양
      ctx.save();
      ctx.translate(b.x,b.y);
      ctx.rotate(t*0.8);
      ctx.fillStyle = ink2;
      ctx.strokeStyle = ink;
      ctx.lineWidth = 2;
      ctx.beginPath();
      for (let k=0;k<10;k++){
        const a=(Math.PI*2/10)*k - Math.PI/2;
        const rr = k%2===0 ? b.r*1.15 : b.r*0.5;
        ctx.lineTo(Math.cos(a)*rr, Math.sin(a)*rr);
      }
      ctx.closePath(); ctx.fill(); ctx.stroke();
      ctx.restore();
      ctx.fillStyle = MAP.key==='abyss' ? '#232427' : '#f6f6f4';
      ctx.beginPath(); ctx.arc(b.x-5,b.y-3,2.4,0,Math.PI*2); ctx.arc(b.x+5,b.y-3,2.4,0,Math.PI*2); ctx.fill();

    } else if (b.kind==='wind'){
      // 유진콩 — 콩 모양 몸체 + 바람
      ctx.save();
      ctx.translate(b.x,b.y);
      ctx.fillStyle = ink2;
      ctx.strokeStyle = ink;
      ctx.lineWidth = 1.6;
      ctx.beginPath();
      ctx.ellipse(0, 0, b.r*0.75, b.r*1.05, face*0.2, 0, Math.PI*2);
      ctx.fill(); ctx.stroke();
      ctx.fillStyle = MAP.key==='abyss' ? '#232427' : '#f6f6f4';
      ctx.beginPath(); ctx.arc(face*5,-6,2.4,0,Math.PI*2); ctx.arc(face*11,-5,2.4,0,Math.PI*2); ctx.fill();
      ctx.strokeStyle = mid;
      ctx.lineWidth = 1.8;
      for (let k=0;k<3;k++){
        const a = t*3 + k*(Math.PI*2/3);
        ctx.beginPath();
        ctx.arc(Math.cos(a)*(b.r+10), Math.sin(a)*(b.r+10), 7, a, a+2.2);
        ctx.stroke();
      }
      ctx.restore();

    } else {
      // 인간형 보스들 — v6.60: 숨쉬기 스케일 + 악센트 발광 눈 (살아있는 위압)
      const breath = 1 + Math.sin(t*2.2 + b.x*0.01)*0.025;
      const scale = 1.9 * (b.emp?1.1:1) * (b.finale?1.5:1) * breath;
      const walk = t*8;
      let robe = (b.kind==='backstab'||b.kind==='esper'||b.kind==='summoner'||b.kind==='root');
      drawHumanoid(b.x, b.y-4, { face, walk, gear:null, scale, ink: b.emp? ink : ink2, robe, boss:true, tierC: BOSS_ACCENTS[b.key], pal: bossPal(b.key, b.emp) });
      ctx.save();
      ctx.translate(b.x, b.y-4);
      ctx.scale(face*scale, scale);
      ctx.strokeStyle = ink;
      ctx.fillStyle = ink;
      ctx.lineCap = 'round';
      ctx.lineWidth = 1.6;

      if (b.kind==='root'){ // 각성 오서진: 안경 + 왕관 + 궤도 구슬 3개
        ctx.beginPath(); ctx.arc(-1,-11,2.6,0,Math.PI*2); ctx.stroke();
        ctx.beginPath(); ctx.arc(4.6,-11,2.6,0,Math.PI*2); ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(-5,-16); ctx.lineTo(-3,-21); ctx.lineTo(0,-17); ctx.lineTo(2,-22); ctx.lineTo(4,-17); ctx.lineTo(7,-21); ctx.lineTo(8,-16);
        ctx.closePath(); ctx.fill();
        for (let k=0;k<3;k++){
          const oa = t*3 + k*(Math.PI*2/3);
          ctx.beginPath(); ctx.arc(Math.cos(oa)*16, -6+Math.sin(oa)*7, 2.8, 0, Math.PI*2); ctx.fill();
        }
      } else if (b.kind==='ranged'){ // 오서진: 안경 + 마법 구슬
        ctx.beginPath(); ctx.arc(-1,-11,2.6,0,Math.PI*2); ctx.stroke();
        ctx.beginPath(); ctx.arc(4.6,-11,2.6,0,Math.PI*2); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(1.6,-11); ctx.lineTo(2,-11); ctx.stroke();
        const oa = t*4;
        ctx.beginPath(); ctx.arc(11+Math.cos(oa)*2, -14+Math.sin(oa)*2, 3.2, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(11+Math.cos(oa)*2, -14+Math.sin(oa)*2, 5.6, 0, Math.PI*2); ctx.stroke();
      } else if (b.kind==='charger'){ // 박태영: 뿔 투구 + 주먹
        ctx.beginPath(); ctx.moveTo(-4,-15); ctx.lineTo(-8,-22); ctx.lineTo(-1,-16); ctx.closePath(); ctx.fill();
        ctx.beginPath(); ctx.moveTo(6,-15); ctx.lineTo(10,-22); ctx.lineTo(3,-16); ctx.closePath(); ctx.fill();
        ctx.beginPath(); ctx.arc(8,2,3.4,0,Math.PI*2); ctx.fill();
        if (b.chargeState==='idle'){
          const def = BOSS_TYPES.parktaeyoung;
          const tg = Math.min(1, b.gauge/def.gaugeTime);
          ctx.strokeStyle = ink;
          ctx.lineWidth = 1.4;
          ctx.beginPath(); ctx.arc(1,-2,14,-Math.PI/2,-Math.PI/2+Math.PI*2*tg); ctx.stroke();
        }
      } else if (b.kind==='summoner'){ // 이원근: 지팡이 + 소환진
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(8,6); ctx.lineTo(8,-18); ctx.stroke();
        ctx.beginPath(); ctx.arc(8,-20,2.6,0,Math.PI*2); ctx.fill();
        if (b.summonT < 1.2){
          ctx.strokeStyle = mid;
          ctx.setLineDash([4,4]);
          ctx.beginPath(); ctx.arc(0,10,14+Math.sin(t*8)*2,0,Math.PI*2); ctx.stroke();
          ctx.setLineDash([]);
        }
      } else if (b.kind==='beam'){ // 이민기: 외눈 렌즈
        ctx.beginPath(); ctx.arc(2,-11,4.4,0,Math.PI*2); ctx.stroke();
        ctx.beginPath(); ctx.arc(2,-11,1.8,0,Math.PI*2); ctx.fill();
      } else if (b.kind==='fickle'){ // 슬기짱: 긴 머리 + 하트
        ctx.lineWidth = 2.2;
        ctx.beginPath(); ctx.moveTo(-4,-14); ctx.quadraticCurveTo(-9,-6,-7,4); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(-2,-16); ctx.quadraticCurveTo(-11,-8,-10,6); ctx.stroke();
        const hb = 1+Math.sin(t*5)*0.15;
        ctx.save();
        ctx.translate(11,-16); ctx.scale(hb,hb);
        ctx.beginPath();
        ctx.arc(-1.6,0,2,0,Math.PI*2); ctx.arc(1.6,0,2,0,Math.PI*2);
        ctx.moveTo(-3.4,0.8); ctx.lineTo(0,4.6); ctx.lineTo(3.4,0.8);
        ctx.fill();
        ctx.restore();
      } else if (b.kind==='mortar'){ // 최병우: 등 뒤 박격포
        ctx.lineWidth = 3.4;
        ctx.beginPath(); ctx.moveTo(-6,0); ctx.lineTo(-12,-14); ctx.stroke();
        ctx.fillRect(-14.5,-18,5,5);
      } else if (b.kind==='clones'){ // 지은이: 리본
        ctx.lineWidth = 1.8;
        ctx.beginPath(); ctx.moveTo(-3,-15); ctx.lineTo(-7,-20); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(5,-15); ctx.lineTo(9,-20); ctx.stroke();
      } else if (b.kind==='berserk'){ // 은재: 대검 + 분노
        ctx.lineWidth = 4;
        ctx.beginPath(); ctx.moveTo(6,2); ctx.lineTo(18,-14); ctx.stroke();
        ctx.lineWidth = 1.8;
        ctx.beginPath(); ctx.moveTo(9.5,-3.5); ctx.lineTo(13,0); ctx.stroke();
        if (b.frenzy>0 || b.hp<b.maxHp*0.5){
          ctx.beginPath(); ctx.moveTo(-6,-18); ctx.lineTo(-3,-21); ctx.moveTo(-8,-14); ctx.lineTo(-11,-16); ctx.stroke();
        }
      } else if (b.kind==='backstab'){ // 정우팍: 단검 + 능글눈
        ctx.lineWidth = 2.2;
        ctx.beginPath(); ctx.moveTo(6,0); ctx.lineTo(12,-5); ctx.stroke();
        ctx.fillStyle = MAP.key==='abyss' ? '#232427' : '#f6f6f4';
        ctx.fillRect(1.5,-12.6,4,1.6);
      } else if (b.kind==='mines'){ // 선정팩: 공병 헬멧 + 가방
        ctx.beginPath(); ctx.arc(1,-13,6.4,Math.PI,0); ctx.fill();
        roundRect(-10,-4,5,8,2); ctx.fill();
        ctx.fillStyle = MAP.key==='abyss' ? '#232427' : '#f6f6f4';
        ctx.beginPath(); ctx.arc(-7.5,0,1.4,0,Math.PI*2); ctx.fill();
      } else if (b.kind==='esper'){ // 눅눅근EX: 긴 머리 + 염동 링
        ctx.lineWidth = 2.2;
        ctx.beginPath(); ctx.moveTo(-3,-15); ctx.quadraticCurveTo(-10,-4,-8,8); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(5,-15); ctx.quadraticCurveTo(12,-4,10,8); ctx.stroke();
        ctx.strokeStyle = mid;
        ctx.lineWidth = 1.4;
        ctx.save();
        ctx.rotate(t*2);
        ctx.beginPath(); ctx.ellipse(1,-6,14,5,0,0,Math.PI*2); ctx.stroke();
        ctx.restore();
        ctx.save();
        ctx.rotate(-t*1.5);
        ctx.beginPath(); ctx.ellipse(1,-6,11,4,Math.PI/3,0,Math.PI*2); ctx.stroke();
        ctx.restore();
      } else if (b.kind==='jealous'){ // 의부증 전여친 은재: 긴 생머리 + 빛나는 핸드폰
        ctx.lineWidth = 2.2;
        ctx.beginPath(); ctx.moveTo(-4,-15); ctx.quadraticCurveTo(-9,-2,-8,10); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(6,-15); ctx.quadraticCurveTo(11,-2,10,10); ctx.stroke();
        const glow = 0.5+Math.sin(t*6)*0.3;
        ctx.fillStyle = 'rgba(201,79,138,'+glow+')';
        ctx.fillRect(9,-6,5,8);
        ctx.strokeStyle = ink; ctx.lineWidth = 1.2;
        ctx.strokeRect(9,-6,5,8);
      } else if (b.kind==='protest'){ // 시위대장: 붉은 머리띠 + 피켓
        ctx.strokeStyle = '#b8362e'; ctx.lineWidth = 2.6;
        ctx.beginPath(); ctx.moveTo(-5,-14); ctx.lineTo(9,-14); ctx.stroke();
        ctx.strokeStyle = ink; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(10,4); ctx.lineTo(10,-22); ctx.stroke();
        ctx.fillStyle = MAP.key==='abyss' ? '#3a3b40' : '#e8e6e0';
        ctx.fillRect(4,-30,13,9);
        ctx.strokeRect(4,-30,13,9);
        ctx.strokeStyle = '#b8362e'; ctx.lineWidth = 1.4;
        ctx.beginPath(); ctx.moveTo(6,-25.5); ctx.lineTo(15,-25.5); ctx.stroke();
      } else if (b.kind==='heatwave'){ // 폭염: 태양 광배 — 방사 광선이 고동친다
        ctx.strokeStyle = 'rgba(212,119,46,0.85)';
        ctx.lineWidth = 2;
        const pulse = 1+Math.sin(t*4)*0.12;
        for (let k=0;k<8;k++){
          const a2 = t*0.8 + k*(Math.PI/4);
          ctx.beginPath();
          ctx.moveTo(Math.cos(a2)*14*pulse, -6+Math.sin(a2)*14*pulse);
          ctx.lineTo(Math.cos(a2)*21*pulse, -6+Math.sin(a2)*21*pulse);
          ctx.stroke();
        }
        ctx.beginPath(); ctx.arc(1,-6,12*pulse,0,Math.PI*2); ctx.stroke();
      } else if (b.kind==='blinddate'){ // 주선자: 나비넥타이 + 명함 다발
        ctx.fillStyle = '#b85c8a';
        ctx.beginPath(); ctx.moveTo(1,-7); ctx.lineTo(-4,-10); ctx.lineTo(-4,-4); ctx.closePath(); ctx.fill();
        ctx.beginPath(); ctx.moveTo(1,-7); ctx.lineTo(6,-10); ctx.lineTo(6,-4); ctx.closePath(); ctx.fill();
        ctx.strokeStyle = ink; ctx.lineWidth = 1.2;
        ctx.fillStyle = MAP.key==='abyss' ? '#3a3b40' : '#f0eee8';
        for (let k=0;k<3;k++){ ctx.fillRect(8+k*1.5, -2+k*1.5, 8, 5); ctx.strokeRect(8+k*1.5, -2+k*1.5, 8, 5); }
      } else if (b.kind==='upstairs'){ // 윗집: 실내화 + 진동 아크
        ctx.strokeStyle = '#7a6a52'; ctx.lineWidth = 2;
        const th2 = Math.sin(t*10)*2;
        for (let k=0;k<3;k++){
          ctx.beginPath(); ctx.arc(1, -20-k*4+th2, 7+k*3, -Math.PI*0.8, -Math.PI*0.2); ctx.stroke();
        }
        ctx.fillStyle = '#7a6a52';
        ctx.beginPath(); ctx.ellipse(-4, 9, 5, 2.6, 0, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.ellipse(6, 9, 5, 2.6, 0, 0, Math.PI*2); ctx.fill();
      } else if (b.kind==='jeonse'){ // 전세 사기꾼: 서류가방 + 도망갈 준비된 선글라스
        ctx.fillStyle = '#8a7a3f';
        roundRect(6,-2,10,8,2); ctx.fill();
        ctx.strokeStyle = ink; ctx.lineWidth=1.2; ctx.strokeRect(6,-2,10,8);
        ctx.fillStyle = ink;
        ctx.fillRect(-4,-13,5,3); ctx.fillRect(2.5,-13,5,3);
        ctx.beginPath(); ctx.moveTo(1,-11.5); ctx.lineTo(2.5,-11.5); ctx.stroke();
      } else if (b.kind==='aialgo'){ // AI 알고리즘: 모니터 두상 + 로딩 스피너
        ctx.fillStyle = MAP.key==='abyss' ? '#1a2c30' : '#dff2f5';
        ctx.fillRect(-6,-17,15,11);
        ctx.strokeStyle = '#5ab8c9'; ctx.lineWidth=1.6; ctx.strokeRect(-6,-17,15,11);
        ctx.beginPath(); ctx.arc(1.5,-11.5,3.2, t*4, t*4+Math.PI*1.4); ctx.stroke();
      } else if (b.kind==='gkshield'){ // v6.62 수문장 · 강철 방패기사: 타워 방패 + 절대 방어 배리어 돔
        if (b.gsGroggy>0){
          // 그로기: 방패를 떨어뜨리고 별이 돈다
          ctx.save(); ctx.translate(9,7); ctx.rotate(1.15);
          ctx.fillStyle = '#6a7a8a';
          roundRect(-4,-9,8,18,3); ctx.fill();
          ctx.restore();
          ctx.fillStyle = '#e8c56a';
          for (let k2=0;k2<3;k2++){
            const sa = t*5 + k2*2.1;
            ctx.beginPath(); ctx.arc(1+Math.cos(sa)*8, -19+Math.sin(sa)*2.4, 1.3, 0, Math.PI*2); ctx.fill();
          }
        } else {
          ctx.save(); ctx.translate(9,-2);
          ctx.fillStyle = '#6a7a8a';
          roundRect(-4.5,-10,9,20,3.5); ctx.fill();
          ctx.strokeStyle = MAP.key==='abyss' ? '#232427' : '#f6f6f4';
          ctx.lineWidth = 1.2;
          ctx.beginPath(); ctx.moveTo(0,-6); ctx.lineTo(0,6); ctx.stroke();
          ctx.restore();
        }
        if (b.gsShield>0){
          ctx.save(); ctx.rotate(t*0.9);
          ctx.strokeStyle = 'rgba(106,122,138,0.9)';
          ctx.lineWidth = 2;
          ctx.beginPath();
          for (let k2=0;k2<6;k2++){ const a3=(Math.PI/3)*k2; ctx.lineTo(Math.cos(a3)*17, Math.sin(a3)*17); }
          ctx.closePath(); ctx.stroke();
          ctx.globalAlpha = 0.15 + 0.08*Math.sin(t*6);
          ctx.fillStyle = '#6a7a8a';
          ctx.fill();
          ctx.globalAlpha = 1;
          ctx.restore();
        }
      } else if (b.kind==='gktwin'){ // v6.62 수문장 · 쌍둥이 그림자: 이중 잔상
        ctx.fillStyle = '#7a5ca3';
        ctx.globalAlpha = 0.22;
        ctx.beginPath(); ctx.arc(-6,-3,8,0,Math.PI*2); ctx.fill();
        ctx.globalAlpha = 0.12;
        ctx.beginPath(); ctx.arc(-11,-3,8,0,Math.PI*2); ctx.fill();
        ctx.globalAlpha = 1;
      } else if (b.kind==='gktrain'){ // v6.62 수문장 · 궤도 기관차: 바퀴·굴뚝 연기·전조등
        ctx.strokeStyle = ink; ctx.lineWidth = 1.6;
        for (const wx of [-5,5]){
          ctx.save(); ctx.translate(wx,9); ctx.rotate(t*(b.trDashing?14:5));
          ctx.beginPath(); ctx.arc(0,0,3.2,0,Math.PI*2); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(-3.2,0); ctx.lineTo(3.2,0); ctx.moveTo(0,-3.2); ctx.lineTo(0,3.2); ctx.stroke();
          ctx.restore();
        }
        ctx.fillStyle = ink2;
        ctx.fillRect(-2,-20,5,6);
        ctx.globalAlpha = 0.3;
        for (let k2=0;k2<3;k2++){
          const ph2 = (t*0.7 + k2*0.33)%1;
          ctx.beginPath(); ctx.arc(0.5-ph2*6, -22-ph2*10, 2+ph2*3, 0, Math.PI*2); ctx.fill();
        }
        ctx.globalAlpha = 1;
        if (b.trPrep>0 && Math.floor(performance.now()/120)%2===0){
          ctx.fillStyle = '#e8c56a';
          ctx.beginPath(); ctx.arc(8,-4,2.6,0,Math.PI*2); ctx.fill();
        }
      }
      // v6.66 테마 실물 프롭 (수문장 한정): 엠블럼을 넘어 몸에 걸친다
      if (b.gate && !b.finale){
        if (b.flav==='sns'){        // 미련의 자물쇠: 가슴에 감긴 사슬 + 금빛 자물쇠
          ctx.strokeStyle = '#8a8f99'; ctx.lineWidth = 1.6;
          ctx.setLineDash([3,3]);
          ctx.beginPath(); ctx.moveTo(-7,-6); ctx.lineTo(7,2); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(-7,2); ctx.lineTo(7,-6); ctx.stroke();
          ctx.setLineDash([]);
          ctx.fillStyle = '#d9a53f';
          roundRect(-3,-4,6,5,1); ctx.fill();
          ctx.strokeStyle = '#d9a53f'; ctx.lineWidth = 1.4;
          ctx.beginPath(); ctx.arc(0,-4,2.2,Math.PI,0); ctx.stroke();
        } else if (b.flav==='picket'){ // 선봉 피켓조: 손피켓
          ctx.strokeStyle = ink; ctx.lineWidth = 1.8;
          ctx.beginPath(); ctx.moveTo(9,5); ctx.lineTo(9,-20); ctx.stroke();
          ctx.fillStyle = MAP.key==='abyss' ? '#3a3b40' : '#efe9df';
          ctx.fillRect(4,-28,12,8); ctx.strokeRect(4,-28,12,8);
          ctx.strokeStyle = '#b8362e'; ctx.lineWidth = 1.2;
          ctx.beginPath(); ctx.moveTo(6,-24); ctx.lineTo(14,-24); ctx.stroke();
        } else if (b.flav==='red'){    // 홍위병: 붉은 완장 + 소기(小旗)
          ctx.fillStyle = '#c9403a';
          ctx.fillRect(-8.5,-4,4,3);
          ctx.strokeStyle = ink; ctx.lineWidth = 1.4;
          ctx.beginPath(); ctx.moveTo(8,-4); ctx.lineTo(8,-24); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(8,-24); ctx.lineTo(15,-21); ctx.lineTo(8,-18); ctx.closePath(); ctx.fill();
        } else if (b.flav==='war'){    // 포병 관측수: 쌍안경
          ctx.fillStyle = ink;
          roundRect(-3.5,-12.8,3,4,1); ctx.fill();
          roundRect(1.5,-12.8,3,4,1); ctx.fill();
          ctx.strokeStyle = ink; ctx.lineWidth = 1;
          ctx.beginPath(); ctx.moveTo(-0.5,-10.8); ctx.lineTo(1.5,-10.8); ctx.stroke();
        }
      }
      // v6.61 보스 KEY별 정체성 프롭 — kind 공용 장식 위에 '그 보스'만의 상징을 얹는다
      {
        const bk = b.key;
        ctx.lineWidth = 1.4;
        if (bk==='trumpTariff' || bk==='tariffEx2'){ // 트황상: 금발 스윕 + 붉은 넥타이
          ctx.fillStyle = '#e8c56a';
          ctx.beginPath(); ctx.moveTo(-6,-14); ctx.quadraticCurveTo(0,-20.5,8,-15); ctx.quadraticCurveTo(9,-12,6,-13); ctx.quadraticCurveTo(0,-17,-4,-11.5); ctx.closePath(); ctx.fill();
          ctx.fillStyle = '#c9403a';
          ctx.beginPath(); ctx.moveTo(1,-5); ctx.lineTo(3.6,-5); ctx.lineTo(2.8,4.5); ctx.lineTo(1.8,4.5); ctx.closePath(); ctx.fill();
        } else if (bk==='xiPingping'){ // 시진핑핑이: 단정한 검은 머리 + 붉은 가슴 배지
          ctx.fillStyle = ink;
          ctx.beginPath(); ctx.arc(0.5,-13.2,5.8,Math.PI*0.95,Math.PI*2.05); ctx.fill();
          ctx.fillStyle = '#c9403a';
          ctx.fillRect(-4.6,-4.5,2.8,2);
        } else if (bk==='maoJu'){ // 마오쩌뚱: 인민모 + 붉은 별
          ctx.fillStyle = '#6a7a5a';
          ctx.fillRect(-6.5,-14.6,14,2.4);
          ctx.beginPath(); ctx.arc(0.5,-14.6,5.2,Math.PI,0); ctx.fill();
          ctx.fillStyle = '#c9403a';
          ctx.save(); ctx.translate(0.5,-17);
          ctx.beginPath();
          for (let k2=0;k2<10;k2++){ const a3=(Math.PI/5)*k2-Math.PI/2; const rr2=k2%2?0.9:2.1; ctx.lineTo(Math.cos(a3)*rr2, Math.sin(a3)*rr2); }
          ctx.closePath(); ctx.fill();
          ctx.restore();
        } else if (bk==='eggRice'){ // 계란볶음밥: 웍 + 튀어오르는 밥알
          ctx.strokeStyle = ink; ctx.lineWidth = 2;
          ctx.beginPath(); ctx.arc(10,-1,5,Math.PI*0.05,Math.PI*0.95,true); ctx.stroke();
          ctx.fillStyle = '#e2b23f';
          ctx.beginPath(); ctx.arc(10,-4+Math.sin(t*8)*1.5,2.2,0,Math.PI*2); ctx.fill();
          ctx.beginPath(); ctx.arc(7.5,-6+Math.sin(t*8+1)*1.5,1.4,0,Math.PI*2); ctx.fill();
        } else if (bk==='moscowBear'){ // 모스크바 곰: 곰귀 + 털모자
          ctx.fillStyle = '#7a5c52';
          ctx.beginPath(); ctx.arc(-4,-16.5,2.6,0,Math.PI*2); ctx.arc(6,-16.5,2.6,0,Math.PI*2); ctx.fill();
          ctx.fillRect(-6,-15.2,14,3.4);
        } else if (bk==='kyivDrone'){ // 드론 조종수: 머리 위를 맴도는 미니 드론
          const dz = Math.sin(t*3)*2;
          ctx.fillStyle = '#4c7ab8';
          ctx.fillRect(-1.5,-26+dz,6,3);
          ctx.strokeStyle = '#4c7ab8'; ctx.lineWidth = 1.2;
          ctx.beginPath(); ctx.moveTo(-4.5,-26+dz); ctx.lineTo(9.5,-26+dz); ctx.stroke();
        } else if (bk==='kickboard'){ // 킥보드 폭주: 헬멧 + 발밑 데크
          ctx.fillStyle = '#6a6c70';
          ctx.beginPath(); ctx.arc(1,-13.5,6,Math.PI,0); ctx.fill();
          ctx.fillRect(3,8.5,11,2.2);
          ctx.beginPath(); ctx.arc(13,11.6,2,0,Math.PI*2); ctx.fill();
        } else if (bk==='loanRate'){ // 대출 이자: 지폐 뭉치 + % 각인
          ctx.fillStyle = '#8a6a3f';
          ctx.fillRect(6,-3,9,5.5);
          ctx.strokeStyle = '#f6f6f4'; ctx.lineWidth = 1;
          ctx.beginPath(); ctx.moveTo(7.5,1); ctx.lineTo(13.5,-8); ctx.stroke();
          ctx.beginPath(); ctx.arc(8.4,-6.8,1.3,0,Math.PI*2); ctx.stroke();
          ctx.beginPath(); ctx.arc(12.6,-0.6,1.3,0,Math.PI*2); ctx.stroke();
        } else if (bk==='relativesEx'){ // 명절 친척 연합: 등에 멘 선물 보따리
          ctx.fillStyle = '#a3653f';
          ctx.beginPath(); ctx.arc(-10,0,4.6,0,Math.PI*2); ctx.fill();
          ctx.strokeStyle = ink; ctx.lineWidth = 1.2;
          ctx.beginPath(); ctx.moveTo(-12.4,-3.4); ctx.lineTo(-7.6,-3.4); ctx.stroke();
        } else if (bk==='burnoutEx' || bk==='grayoneEx'){ // 번아웃·회색 군주: 흘러내리는 잿빛 그림자
          ctx.globalAlpha = 0.3;
          ctx.fillStyle = ink;
          for (let k2=0;k2<3;k2++){
            ctx.beginPath(); ctx.arc(-6+k2*6, 12+Math.sin(t*2+k2)*2.2, 2.5, 0, Math.PI*2); ctx.fill();
          }
          ctx.globalAlpha = 1;
        }
      }
      ctx.restore();
    }

    ctx.globalAlpha = 1;
    // v6.64 진자 철퇴: 사슬 + 스파이크 철퇴 2기 (월드 좌표 — 실제 판정 위치 그대로)
    if (b.kind==='gkflail' && !b.ghost){
      for (let k=0;k<2;k++){
        const fa = (b.flA||0) + k*Math.PI;
        const flr = b.flR||70;
        const fx2 = b.x + Math.cos(fa)*flr, fy2 = b.y + Math.sin(fa)*flr;
        ctx.save();
        ctx.strokeStyle = 'rgba(90,95,105,0.85)';
        ctx.lineWidth = 2;
        ctx.setLineDash([4,4]);
        ctx.beginPath(); ctx.moveTo(b.x,b.y); ctx.lineTo(fx2,fy2); ctx.stroke();
        ctx.setLineDash([]);
        // v6.70 전조: 가속 직전 철퇴가 붉게 맥동 — 텍스트 없이 몸으로 읽는 예고
        ctx.fillStyle = (b.flWarn && Math.floor(performance.now()/110)%2===0) ? '#c9403a' : '#4a4f58';
        ctx.beginPath(); ctx.arc(fx2,fy2,10,0,Math.PI*2); ctx.fill();
        ctx.strokeStyle = PAL.ink;
        ctx.lineWidth = 1.4;
        for (let s2=0;s2<8;s2++){
          const sa = (Math.PI/4)*s2 + (b.flA||0);
          ctx.beginPath();
          ctx.moveTo(fx2+Math.cos(sa)*10, fy2+Math.sin(sa)*10);
          ctx.lineTo(fx2+Math.cos(sa)*14.5, fy2+Math.sin(sa)*14.5);
          ctx.stroke();
        }
        ctx.restore();
      }
      if (b.flFast>0){
        ctx.save();
        ctx.strokeStyle = 'rgba(201,64,58,0.5)';
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(b.x,b.y,(b.flR||70)+16,0,Math.PI*2); ctx.stroke();
        ctx.restore();
      }
    }
    // v6.68 거리 심판: 붉은 위험 반경 — 판정 순간 안에 있으면 벌
    if (b.spDistT>0 && !b.ghost){
      ctx.save();
      ctx.strokeStyle = 'rgba(184,54,46,'+(0.35+0.25*Math.sin(performance.now()/90)).toFixed(2)+')';
      ctx.lineWidth = 2.5;
      ctx.beginPath(); ctx.arc(b.x, b.y, 240, 0, Math.PI*2); ctx.stroke();
      ctx.restore();
    }
    // v6.68 응시: 점선 조준선 — 사라지기 전에 측면으로
    if (b.spGazeT>0 && !b.ghost){
      ctx.save();
      ctx.strokeStyle = 'rgba(154,111,196,0.65)';
      ctx.lineWidth = 2;
      ctx.setLineDash([8,6]);
      ctx.beginPath(); ctx.moveTo(b.x, b.y); ctx.lineTo(b.x+Math.cos(b.spGazeA)*900, b.y+Math.sin(b.spGazeA)*900); ctx.stroke();
      ctx.setLineDash([]);
      ctx.restore();
    }
    // v6.65 거울 위병: 플레이어를 향한 거울 패널 — 반사 자세 중 빛난다
    if (b.kind==='gkmirror' && !b.ghost){
      const aimM = Math.atan2(player.y-b.y, player.x-b.x);
      ctx.save();
      ctx.translate(b.x + Math.cos(aimM)*(b.r+10), b.y + Math.sin(aimM)*(b.r+10));
      ctx.rotate(aimM);
      ctx.fillStyle = b.mrReflect>0 ? 'rgba(154,219,232,0.9)'
        : (b.mrWarn && Math.floor(performance.now()/100)%2===0) ? 'rgba(154,219,232,0.75)'
        : 'rgba(154,219,232,0.4)';
      ctx.fillRect(-3,-16,6,32);
      ctx.strokeStyle = PAL.ink;
      ctx.lineWidth = 1.4;
      ctx.strokeRect(-3,-16,6,32);
      if (b.mrReflect>0 && Math.floor(performance.now()/110)%2===0){
        ctx.strokeStyle = '#ffffff';
        ctx.beginPath(); ctx.moveTo(0,-12); ctx.lineTo(0,12); ctx.stroke();
      }
      ctx.restore();
    }
    // v6.65 모래시계 파수꾼: 머리 위 기울어지는 모래시계
    if (b.kind==='gkhour' && !b.ghost){
      ctx.save();
      ctx.translate(b.x, b.y-b.r-26+Math.sin(performance.now()/300)*2);
      ctx.rotate(Math.sin(performance.now()/700)*0.35);
      ctx.strokeStyle = '#5ab8c9';
      ctx.lineWidth = 1.6;
      ctx.beginPath(); ctx.moveTo(-6,-8); ctx.lineTo(6,-8); ctx.lineTo(-6,8); ctx.lineTo(6,8); ctx.closePath(); ctx.stroke();
      ctx.fillStyle = 'rgba(90,184,201,0.55)';
      ctx.beginPath(); ctx.moveTo(-4,6.5); ctx.lineTo(4,6.5); ctx.lineTo(0,1); ctx.closePath(); ctx.fill();
      ctx.restore();
    }
    // v6.65 세금 징수관: 징수 중 금빛 흡입 나선
    if (b.kind==='gktax' && !b.ghost && b.txPull>0){
      ctx.save();
      ctx.strokeStyle = 'rgba(217,165,63,0.6)';
      ctx.lineWidth = 2;
      const rot2 = performance.now()/240;
      for (let k=0;k<3;k++){
        ctx.beginPath(); ctx.arc(b.x, b.y, b.r+14+k*10, rot2+k*2, rot2+k*2+2.2); ctx.stroke();
      }
      ctx.restore();
    }
    // v6.64 테마 수문장 상징: 머리 위 테마 엠블럼 — 어느 세계관의 수문장인지 보인다
    if (b.flav && !b.finale && !b.ghost){
      const EMB = { sns:'🔒', picket:'🪧', sun:'☀️', heart:'💘', noise:'🔊', money:'💸', ad:'📢', work:'📑', family:'🍚', red:'🚩', wall:'🧱', tired:'😩', war:'🎯' };
      const em = EMB[b.flav];
      if (em){
        ctx.save();
        ctx.globalAlpha = 0.92;
        ctx.font = '14px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(em, b.x + 26, b.y - b.r - 22 + Math.sin(performance.now()/350)*2.2);
        ctx.restore();
      }
    }
    // v6.62 쌍둥이 공명 실: 본체와 분신을 잇는 점선 — "분신부터"가 눈에 보인다
    if (b.kind==='gktwin' && b.gtClone && enemies.includes(b.gtClone)){
      ctx.save();
      ctx.strokeStyle = 'rgba(122,92,163,0.5)';
      ctx.lineWidth = 1.6;
      ctx.setLineDash([5,6]);
      ctx.lineDashOffset = -performance.now()/50;
      ctx.beginPath(); ctx.moveTo(b.x,b.y); ctx.lineTo(b.gtClone.x,b.gtClone.y); ctx.stroke();
      ctx.setLineDash([]);
      ctx.restore();
    }
    // 보스 시그니처 색 링 (분노 시 고동친다)
    const accent = BOSS_ACCENTS[b.key];
    if (accent && !b.ghost){
      ctx.strokeStyle = accent;
      if (b.enraged){
        const ep = 1 + Math.sin(performance.now()/110)*0.12;
        ctx.globalAlpha = 0.75;
        ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(b.x, b.y, (b.r+14)*ep, 0, Math.PI*2); ctx.stroke();
      }
      ctx.globalAlpha = 0.55;
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(b.x, b.y+b.r*0.85, b.r*0.95, 0, Math.PI*2); ctx.stroke();
      ctx.globalAlpha = 1;
    }
    // 강화형 오라 (붉은 위협 표시)
    if (b.emp && !b.ghost){
      ctx.strokeStyle = COLORS.danger;
      ctx.lineWidth = 1.5;
      ctx.setLineDash([3,6]);
      ctx.lineDashOffset = performance.now()/40;
      ctx.beginPath(); ctx.arc(b.x, b.y, b.r+16, 0, Math.PI*2); ctx.stroke();
      ctx.setLineDash([]);
    }
    // 이름표 (시그니처 색) — v6.70 위로 분리 + 헤일로 스트로크 (핍·엠블럼·몸에 안 가려진다)
    ctx.font = "700 11px 'IBM Plex Sans KR', sans-serif";
    ctx.textAlign = 'center';
    ctx.strokeStyle = MAP.key==='abyss' ? 'rgba(18,19,22,0.85)' : 'rgba(246,246,244,0.92)';
    ctx.lineWidth = 3;
    ctx.strokeText(b.name, b.x, b.y-b.r-40);
    ctx.fillStyle = BOSS_ACCENTS[b.key] || PAL.ink;
    ctx.fillText(b.name, b.x, b.y-b.r-40);
    ctx.restore();
  }

  // ---------- 이펙트/오브젝트 렌더링 ----------
  function drawAura(){
    if (!auraState.on) return;
    ctx.save();
    const pulse = 1 + Math.sin(performance.now()/300)*0.02;
    const r = auraState.r * pulse;
    const dark = MAP.key==='abyss';
    ctx.fillStyle = dark ? 'rgba(255,255,255,0.06)' : 'rgba(32,33,36,0.05)';
    ctx.beginPath(); ctx.arc(player.x, player.y, r, 0, Math.PI*2); ctx.fill();
    ctx.strokeStyle = dark ? (auraState.ev?'rgba(255,255,255,0.4)':'rgba(255,255,255,0.2)') : (auraState.ev?'rgba(0,0,0,0.35)':'rgba(0,0,0,0.18)');
    ctx.lineWidth = auraState.ev ? 2 : 1.2;
    ctx.beginPath(); ctx.arc(player.x, player.y, r, 0, Math.PI*2); ctx.stroke();
    ctx.restore();
  }
  // v6.89 기울어진 고리를 화면에 투영한다. 위에서 내려다보는 시점이라 세로를 눌러(0.62) 타원이 된다.
  // z는 깊이 — 양수면 플레이어 앞, 음수면 뒤. 이걸로 위성이 몸을 돌아 지나가는 게 보인다
  const SAT_SQUASH = 0.94;   // v6.92 거의 안 눕힌다 — 고리가 서 있어야 위아래로 넘어간다
  function ringPoint(a, tilt, ph, R){
    const lx = Math.cos(a)*R, ly = Math.sin(a)*R;
    // v6.92 화면 Y축 기준으로 기울인다 → 가로 성분이 깊이가 되고 세로 성분은 살아남는다.
    // 결과: 구체가 위로 올라가며 안쪽으로 들어갔다가, 아래로 내려오며 앞으로 나온다
    const x2 = lx*Math.cos(tilt), z = lx*Math.sin(tilt);
    const c = Math.cos(ph), sn = Math.sin(ph);                  // 세운 고리를 화면상에서 굴린다
    return { x: x2*c - ly*sn, y: (x2*sn + ly*c)*SAT_SQUASH, z };
  }
  function drawSatRing(rg, alpha){
    ctx.save();
    ctx.translate(player.x, player.y);
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    for (let i=0;i<=48;i++){
      const q = ringPoint((Math.PI*2/48)*i, rg.tilt, rg.ph, rg.r);
      if (i===0) ctx.moveTo(q.x,q.y); else ctx.lineTo(q.x,q.y);
    }
    ctx.stroke();
    ctx.restore();
  }
  function drawSatOrbs(front){
    for (const sp of satPos){
      if (front !== ((sp.z||0) > 0)) continue;
      // v6.91 깊이 강조: 크기 ±75% + 뒤쪽은 더 흐리게 + 살짝 위로(원근) → z축 통과가 눈에 보인다
      const zn = (sp.z||0)/Math.max(1,sp.orbitR);               // -1(뒤) ~ +1(앞)
      const dep = 1 + zn*0.75;
      const rr = Math.max(2.5, (sp.ev?8:6)*dep);
      ctx.globalAlpha = front ? 1 : 0.42;
      ctx.fillStyle = sp.ev ? PAL.ink : PAL.ink2;
      ctx.beginPath(); ctx.arc(sp.x, sp.y - (zn<0 ? -zn*3 : 0), rr, 0, Math.PI*2); ctx.fill();
      if (front && sp.ev){ ctx.strokeStyle='#7ec4e8'; ctx.lineWidth=1.4; ctx.stroke(); }
      if (front){                                               // 앞으로 나온 구체엔 하이라이트
        ctx.globalAlpha = 0.5; ctx.fillStyle = '#dff6fb';
        ctx.beginPath(); ctx.arc(sp.x - rr*0.3, sp.y - rr*0.35, rr*0.32, 0, Math.PI*2); ctx.fill();
      }
    }
    ctx.globalAlpha = 1;
  }
  function drawSatellites(){          // 플레이어 뒤쪽 반: 고리 + 뒤로 돈 위성
    if (!satPos.length) return;
    ctx.save();
    ctx.strokeStyle = satPos[0].ev ? PAL.ink : PAL.soft;
    ctx.lineWidth = satPos[0].ev ? 2.2 : 1;
    for (const rg of satRings) drawSatRing(rg, 0.5);
    drawSatOrbs(false);
    ctx.restore();
  }
  function drawSatellitesFront(){     // 플레이어 앞쪽 반 — 캐릭터 위에 겹쳐 그린다
    if (satPos.length){
      ctx.save();
      drawSatOrbs(true);
      ctx.restore();
    }
    drawSatFlight();
  }
  // v6.147 사출 위성 — 나갈 땐 꼬리를 끌고, 돌아올 땐 나와 실로 이어진다 (회수 경로가 눈에 보여야 조작이 된다)
  function drawSatFlight(){
    if (!satFlight.length) return;
    ctx.save();
    for (const f of satFlight){
      if (f.phase==='back'){
        ctx.globalAlpha = 0.32; ctx.strokeStyle = '#7ec4e8'; ctx.lineWidth = 1;
        ctx.setLineDash([3,4]);
        ctx.beginPath(); ctx.moveTo(f.x,f.y); ctx.lineTo(player.x,player.y); ctx.stroke();
        ctx.setLineDash([]);
      }
      ctx.globalAlpha = 1;
      ctx.fillStyle = f.ev ? PAL.ink : PAL.ink2;
      ctx.beginPath(); ctx.arc(f.x, f.y, f.ev?9:7, 0, Math.PI*2); ctx.fill();
      ctx.strokeStyle = '#7ec4e8'; ctx.lineWidth = 1.6; ctx.stroke();
      ctx.globalAlpha = 0.5; ctx.fillStyle = '#dff6fb';
      ctx.beginPath(); ctx.arc(f.x-2, f.y-2.4, 2.4, 0, Math.PI*2); ctx.fill();
    }
    ctx.globalAlpha = 1;
    ctx.restore();
  }
  function drawDrones(){
    for (const dr of dronePos){
      ctx.save();
      ctx.translate(dr.x, dr.y);
      ctx.fillStyle = PAL.ink2;
      roundRect(-5,-3,10,6,2); ctx.fill();
      ctx.strokeStyle = PAL.ink;
      ctx.lineWidth = 1.4;
      ctx.save();
      ctx.rotate(performance.now()/40);
      ctx.beginPath(); ctx.moveTo(-7,0); ctx.lineTo(7,0); ctx.stroke();
      ctx.restore();
      ctx.restore();
    }
  }
  function drawZones(){
    // Pixi 3단계: 장판의 '빛' 자체는 WebGL 광원 디스크로 (형태 요소는 캔버스 유지)
    if (FX.enabled){
      const fxZones = [];
      for (const z of zones){
        if (z.type==='shade' || z.type==='mirage') continue; // 그늘·신기루는 빛이 아니라 어둠 — 캔버스에서만
        const tt = Math.min(1, z.t/z.maxT);
        const tint = z.type==='fire' ? 0xe2603f : z.type==='void' ? 0x9a6fc4 : z.type==='grav' ? 0x6a5acd : z.type==='frost' ? 0x3fa8c9 : z.type==='block' ? 0xb8362e : z.type==='gore' ? 0xa3302c : 0x6faa4e;
        fxZones.push({ x:z.x, y:z.y, r:z.r, tint, alpha:(z.type==='block'?0.12:0.22)*tt });
      }
      // Pixi 4단계: 보스 오라 — 시그니처 색 광원 (분노 시 강렬하게)
      for (const b of bosses){
        if (b.ghost) continue;
        const ac = BOSS_ACCENTS[b.key];
        const tint = ac ? parseInt(ac.slice(1),16) : 0xb8362e;
        fxZones.push({ x:b.x, y:b.y, r:b.r*2.1, tint, alpha: b.enraged ? 0.30 : 0.16 });
      }
      // 주력 속성 오라: 3P 이상 투자한 원소 색으로 은은한 개인 광원
      const de = dominantElemColor();
      if (de && player){
        fxZones.push({ x:player.x, y:player.y, r:30, tint:parseInt(de.slice(1),16), alpha:0.10 });
      }
      FX.drawZones(fxZones);
    }
    for (const z of zones){
      const tt = Math.min(1, z.t/z.maxT);
      ctx.save();
      ctx.translate(z.x, z.y);
      if (z.type==='fire'){
        const flick = 0.9 + Math.sin(performance.now()/60 + z.x)*0.1;
        if (!FX.enabled){
          ctx.fillStyle = 'rgba(226,96,63,'+(0.16*tt)+')';
          ctx.beginPath(); ctx.arc(0,0,z.r*flick,0,Math.PI*2); ctx.fill();
        }
        ctx.strokeStyle = 'rgba(226,96,63,'+(0.6*tt)+')';
        ctx.lineWidth = 1.5;
        for (let k=0;k<3;k++){
          const a = performance.now()/300 + k*2.1 + z.x;
          const fx2 = Math.cos(a)*z.r*0.5, fy2 = Math.sin(a)*z.r*0.5;
          ctx.beginPath();
          ctx.moveTo(fx2, fy2+3); ctx.quadraticCurveTo(fx2+2, fy2-4, fx2, fy2-7);
          ctx.stroke();
        }
      } else if (z.type==='frost'){
        // 눈보라: 흩날리는 눈송이
        if (!FX.enabled){
          ctx.fillStyle = 'rgba(63,168,201,'+(0.14*tt)+')';
          ctx.beginPath(); ctx.arc(0,0,z.r,0,Math.PI*2); ctx.fill();
        }
        ctx.strokeStyle = 'rgba(63,168,201,'+(0.55*tt)+')';
        ctx.lineWidth = 1.3;
        ctx.beginPath(); ctx.arc(0,0,z.r,0,Math.PI*2); ctx.stroke();
        ctx.fillStyle = 'rgba(220,240,248,'+(0.8*tt)+')';
        for (let k=0;k<5;k++){
          const st = (performance.now()/600 + k*0.37) % 1;
          const sa = k*1.9 + z.x*0.01;
          ctx.beginPath();
          ctx.arc(Math.cos(sa)*z.r*0.6, Math.sin(sa)*z.r*0.6 - 10 + st*20, 2, 0, Math.PI*2);
          ctx.fill();
        }
      } else if (z.type==='grav'){
        // 중력 우물: 안으로 빨려드는 궤도선
        if (!FX.enabled){
          ctx.fillStyle = 'rgba(106,90,205,'+(0.20*tt)+')';
          ctx.beginPath(); ctx.arc(0,0,z.r,0,Math.PI*2); ctx.fill();
        }
        ctx.strokeStyle = 'rgba(106,90,205,'+(0.65*tt)+')';
        ctx.lineWidth = 1.4;
        const gr2 = performance.now()/500;
        for (let k=0;k<3;k++){
          const rr = z.r * (1 - ((gr2 + k/3) % 1));
          ctx.globalAlpha = (rr/z.r)*0.7*tt;
          ctx.beginPath(); ctx.arc(0,0,rr,0,Math.PI*2); ctx.stroke();
        }
        ctx.globalAlpha = 1;
        ctx.fillStyle = '#241d3a';
        ctx.beginPath(); ctx.arc(0,0,5,0,Math.PI*2); ctx.fill();
      } else if (z.type==='void'){
        if (!FX.enabled){
          ctx.fillStyle = 'rgba(92,74,138,'+(0.22*tt)+')';
          ctx.beginPath(); ctx.arc(0,0,z.r,0,Math.PI*2); ctx.fill();
        }
        ctx.strokeStyle = 'rgba(154,111,196,'+(0.7*tt)+')';
        ctx.lineWidth = 2;
        ctx.save();
        ctx.rotate(performance.now()/400);
        ctx.beginPath(); ctx.ellipse(0,0,z.r*0.8,z.r*0.4,0,0,Math.PI*2); ctx.stroke();
        ctx.restore();
        ctx.fillStyle = '#1a1420';
        ctx.beginPath(); ctx.arc(0,0,7,0,Math.PI*2); ctx.fill();
      } else if (z.type==='block'){
        // 시위 바리케이드: 줄무늬 통제선 원통 — 통행 불가
        ctx.fillStyle = MAP.key==='abyss' ? 'rgba(60,44,46,'+(0.85*tt)+')' : 'rgba(200,180,168,'+(0.9*tt)+')';
        ctx.strokeStyle = 'rgba(184,54,46,'+(0.85*tt)+')';
        ctx.lineWidth = 2.4;
        ctx.beginPath(); ctx.arc(0,0,z.r,0,Math.PI*2); ctx.fill(); ctx.stroke();
        // 경고 사선 줄무늬
        ctx.save();
        ctx.beginPath(); ctx.arc(0,0,z.r-3,0,Math.PI*2); ctx.clip();
        ctx.strokeStyle = 'rgba(184,54,46,'+(0.5*tt)+')';
        ctx.lineWidth = 4;
        for (let k=-3;k<=3;k++){
          ctx.beginPath(); ctx.moveTo(k*10-z.r, z.r); ctx.lineTo(k*10+z.r, -z.r); ctx.stroke();
        }
        ctx.restore();
      } else if (z.type==='silence'){
        // 어색한 침묵: 잿빛 정적 — 안에서는 스킬이 나가지 않는다
        ctx.fillStyle = 'rgba(120,118,114,0.16)';
        ctx.beginPath(); ctx.arc(0,0,z.r,0,Math.PI*2); ctx.fill();
        ctx.strokeStyle = 'rgba(90,88,84,'+(0.6*tt)+')';
        ctx.setLineDash([2,7]);
        ctx.lineWidth = 1.6;
        ctx.beginPath(); ctx.arc(0,0,z.r,0,Math.PI*2); ctx.stroke();
        ctx.setLineDash([]);
        ctx.fillStyle = 'rgba(90,88,84,0.7)';
        ctx.font = '11px "IBM Plex Mono", monospace';
        ctx.textAlign='center';
        ctx.fillText('. . .', 0, 3);
      } else if (z.type==='shade'){
        // 폭염 속 한 뼘의 그늘: 유일한 안식처
        ctx.fillStyle = 'rgba(30,36,52,0.30)';
        ctx.beginPath(); ctx.arc(0,0,z.r,0,Math.PI*2); ctx.fill();
        ctx.strokeStyle = 'rgba(90,140,200,0.55)';
        ctx.setLineDash([6,6]);
        ctx.lineWidth = 1.8;
        ctx.beginPath(); ctx.arc(0,0,z.r,0,Math.PI*2); ctx.stroke();
        ctx.setLineDash([]);
      } else if (z.type==='mirage'){
        // 신기루: 그늘과 닮았지만 테두리가 불그스름하게 아른거린다 — 관찰력이 생명
        const wob = Math.sin(performance.now()/180 + z.x)*0.08;
        ctx.fillStyle = 'rgba(38,34,46,'+(0.26+wob)+')';
        ctx.beginPath(); ctx.arc(0,0,z.r,0,Math.PI*2); ctx.fill();
        ctx.strokeStyle = 'rgba(190,110,90,0.5)';
        ctx.setLineDash([6,6]);
        ctx.lineWidth = 1.8;
        ctx.beginPath(); ctx.arc(0,0,z.r,0,Math.PI*2); ctx.stroke();
        ctx.setLineDash([]);
      } else {
        if (!FX.enabled){
          ctx.fillStyle = 'rgba(111,170,78,'+(0.13*tt)+')';
          ctx.beginPath(); ctx.arc(0,0,z.r,0,Math.PI*2); ctx.fill();
        }
        ctx.strokeStyle = 'rgba(111,170,78,'+(0.55*tt)+')';
        ctx.setLineDash([4,5]);
        ctx.lineWidth = 1.4;
        ctx.beginPath(); ctx.arc(0,0,z.r,0,Math.PI*2); ctx.stroke();
        ctx.setLineDash([]);
        // 거품
        for (let k=0;k<3;k++){
          const bt = (performance.now()/500 + k*0.37 + z.x*0.01) % 1;
          const ba = k*2.4 + z.x;
          ctx.globalAlpha = (1-bt)*0.4*tt;
          ctx.beginPath();
          ctx.arc(Math.cos(ba)*z.r*0.5, Math.sin(ba)*z.r*0.5 - bt*14, 2.5, 0, Math.PI*2);
          ctx.stroke();
          ctx.globalAlpha = 1;
        }
      }
      ctx.restore();
    }
  }
  function drawGhosts(){
    for (const gh of (player.ghosts||[])){
      ctx.save();
      ctx.globalAlpha = 0.55 * Math.min(1, gh.t/2);
      ctx.fillStyle = '#8fa89a';
      ctx.beginPath();
      ctx.arc(gh.x, gh.y-4, 7, Math.PI, 0);
      ctx.lineTo(gh.x+7, gh.y+5);
      const wob = Math.sin(performance.now()/120+gh.x)*2;
      ctx.quadraticCurveTo(gh.x+3.5, gh.y+8+wob, gh.x, gh.y+5);
      ctx.quadraticCurveTo(gh.x-3.5, gh.y+8-wob, gh.x-7, gh.y+5);
      ctx.closePath(); ctx.fill();
      ctx.fillStyle = '#232427';
      ctx.beginPath(); ctx.arc(gh.x-2,gh.y-5,1.3,0,Math.PI*2); ctx.arc(gh.x+2,gh.y-5,1.3,0,Math.PI*2); ctx.fill();
      ctx.restore();
      ctx.globalAlpha = 1;
    }
  }
  function drawShadows(){
    for (const sh of (player.shadows||[])){
      ctx.save();
      ctx.globalAlpha = 0.35 * Math.min(1, sh.t/1);
      drawHumanoid(sh.x, sh.y, { face:player.faceX, walk:performance.now()/90, gear:player.classKey, scale:1.1, ink:'#8b5cf6' });
      ctx.restore();
      ctx.globalAlpha = 1;
    }
  }
  function drawTurrets(){
    for (const tu of (player.turrets||[])){
      ctx.save();
      ctx.translate(tu.x, tu.y);
      ctx.fillStyle = PAL.ink2;
      roundRect(-6,-4,12,9,2); ctx.fill();
      ctx.fillStyle = PAL.ink;
      const t2 = nearestTarget();
      const aim = t2 ? Math.atan2(t2.y-tu.y, t2.x-tu.x) : 0;
      ctx.save(); ctx.rotate(aim);
      ctx.fillRect(0,-1.6,11,3.2);
      ctx.restore();
      ctx.beginPath(); ctx.arc(0,-6,2.5,0,Math.PI*2); ctx.fill();
      ctx.restore();
    }
  }
  function drawItems(){
    for (const it of items){
      const blink = it.age>16 && it.type!=='chest' && (Math.floor(it.age*6)%2===0);
      if (blink) continue;
      ctx.save();
      ctx.translate(it.x, it.y + Math.sin(performance.now()/280 + it.x)*2);
      ctx.strokeStyle = PAL.ink2;
      ctx.lineWidth = 1.5;
      if (it.type==='chest'){
        const pulse = 1 + Math.sin(performance.now()/200)*0.06;
        ctx.scale(pulse, pulse);
        ctx.fillStyle = COLORS.chest;
        ctx.strokeStyle = '#8a6428';
        roundRect(-10,-8,20,16,3); ctx.fill(); ctx.stroke();
        ctx.strokeStyle = '#f4e6c8';
        ctx.beginPath(); ctx.moveTo(-10,-2); ctx.lineTo(10,-2); ctx.stroke();
        ctx.fillStyle = COLORS.gold;
        ctx.fillRect(-2,-4,4,5);
      } else if (it.type==='gold'){
        ctx.fillStyle = COLORS.gold;
        ctx.strokeStyle = '#a87c28';
        ctx.beginPath(); ctx.moveTo(0,-7); ctx.lineTo(6,0); ctx.lineTo(0,7); ctx.lineTo(-6,0); ctx.closePath();
        ctx.fill(); ctx.stroke();
      } else if (it.type==='heal'){
        ctx.fillStyle = '#ffffff';
        ctx.beginPath(); ctx.arc(0,0,8,0,Math.PI*2); ctx.fill(); ctx.stroke();
        ctx.fillStyle = COLORS.hp;
        ctx.fillRect(-1.7,-5,3.4,10); ctx.fillRect(-5,-1.7,10,3.4);
      } else if (it.type==='magnet'){
        ctx.strokeStyle = COLORS.frost;
        ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(0,0,6.5, Math.PI*0.15, Math.PI*0.85, true); ctx.stroke();
        ctx.fillStyle = COLORS.danger;
        ctx.fillRect(-8.2,2,4,4); ctx.fillRect(4.2,2,4,4);
      } else if (it.type==='freeze'){
        ctx.strokeStyle = COLORS.frost;
        ctx.lineWidth = 1.6;
        for (let k=0;k<3;k++){
          const a=(Math.PI/3)*k;
          ctx.beginPath();
          ctx.moveTo(Math.cos(a)*-7, Math.sin(a)*-7);
          ctx.lineTo(Math.cos(a)*7, Math.sin(a)*7);
          ctx.stroke();
        }
      } else if (it.type==='bomb'){
        ctx.fillStyle = PAL.ink;
        ctx.beginPath(); ctx.arc(0,1,7,0,Math.PI*2); ctx.fill(); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(3,-4); ctx.quadraticCurveTo(7,-9,10,-8); ctx.stroke();
      } else if (it.type==='whet'){
        // 강화석 (모루 모양, 주황)
        ctx.fillStyle = '#e08a2e';
        ctx.strokeStyle = '#8a5418';
        ctx.beginPath(); ctx.moveTo(-8,-2); ctx.lineTo(8,-2); ctx.lineTo(5,3); ctx.lineTo(-5,3); ctx.closePath(); ctx.fill(); ctx.stroke();
        ctx.fillRect(-3,3,6,4);
        ctx.fillStyle = '#f4d9a8';
        ctx.fillRect(-6,-6,12,3);
      } else if (it.type==='scroll'){
        // 리롤 두루마리 (보라)
        ctx.fillStyle = '#f4ecd8';
        ctx.strokeStyle = '#8b5cf6';
        ctx.lineWidth = 1.6;
        roundRect(-7,-9,14,18,3); ctx.fill(); ctx.stroke();
        ctx.strokeStyle = '#8b5cf6';
        ctx.beginPath(); ctx.moveTo(-4,-4); ctx.lineTo(4,-4); ctx.moveTo(-4,0); ctx.lineTo(4,0); ctx.moveTo(-4,4); ctx.lineTo(2,4); ctx.stroke();
      } else if (it.type==='stamp'){
        // 제외 도장 (빨강 금지 마크)
        ctx.strokeStyle = COLORS.danger;
        ctx.lineWidth = 2.4;
        ctx.beginPath(); ctx.arc(0,0,7,0,Math.PI*2); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(-4.5,4.5); ctx.lineTo(4.5,-4.5); ctx.stroke();
      } else if (it.type==='slotchip'){
        // 기억 확장 조각 (청록 퍼즐 조각)
        ctx.fillStyle = '#2aa79b';
        ctx.strokeStyle = '#1c7268';
        ctx.lineWidth = 1.6;
        roundRect(-7,-7,14,14,3); ctx.fill(); ctx.stroke();
        ctx.fillStyle = '#e8fffb';
        ctx.beginPath(); ctx.arc(0,-7,3,0,Math.PI); ctx.fill();
        ctx.beginPath(); ctx.arc(7,0,3,Math.PI/2,Math.PI*1.5); ctx.fill();
        ctx.fillRect(-3,-2,6,4);
      }
      ctx.restore();
    }
    // 차원 균열 포탈
    for (const rf of rifts){
      ctx.save();
      ctx.translate(rf.x, rf.y);
      ctx.rotate(performance.now()/600);
      ctx.strokeStyle = '#5c4a8a';
      ctx.lineWidth = 2.2;
      for (let k=0;k<3;k++){
        ctx.globalAlpha = 0.35 + 0.25*Math.sin(performance.now()/200 + k*2);
        ctx.beginPath(); ctx.arc(0,0, rf.r+4+k*6, k*2, k*2+Math.PI*1.4); ctx.stroke();
      }
      ctx.globalAlpha = 1;
      ctx.fillStyle = '#5c4a8a';
      ctx.beginPath();
      ctx.moveTo(0,-10); ctx.lineTo(8,0); ctx.lineTo(0,10); ctx.lineTo(-8,0); ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
    // 조사 지점
    for (const s of surveys){
      ctx.save();
      ctx.translate(s.x, s.y + Math.sin(performance.now()/300)*3);
      const pulse = 0.7 + Math.sin(performance.now()/250)*0.3;
      ctx.strokeStyle = PAL.ink;
      ctx.globalAlpha = pulse;
      ctx.lineWidth = 1.6;
      ctx.beginPath(); ctx.arc(0,0,s.r+5,0,Math.PI*2); ctx.stroke();
      ctx.globalAlpha = 1;
      ctx.fillStyle = PAL.ink;
      roundRect(-9,-13,18,26,4); ctx.fill();
      ctx.fillStyle = PAL.bg;
      ctx.font = "700 15px 'IBM Plex Mono', monospace";
      ctx.textAlign = 'center';
      ctx.fillText('?', 0, 6);
      ctx.restore();
    }
    // NPC 의뢰인 — 머리 위 노란 느낌표
    for (const cl of clients){
      ctx.save();
      drawShadow(cl.x, cl.y+15, 11);
      drawHumanoid(cl.x, cl.y, { face: player.x>cl.x?1:-1, walk:0, gear:null, scale:1.1, ink:PAL.ink2 });
      ctx.translate(cl.x, cl.y);
      // 서류가방
      ctx.fillStyle = PAL.ink;
      roundRect(6,-2,9,7,2); ctx.fill();
      // 퀘스트 마커 !
      const qb = Math.sin(performance.now()/300)*3;
      ctx.fillStyle = '#e8c56a';
      ctx.font = "700 18px 'IBM Plex Mono', monospace";
      ctx.textAlign = 'center';
      ctx.fillText('!', 0, -28+qb);
      ctx.fillStyle = PAL.ink;
      ctx.font = "600 9px 'IBM Plex Sans KR', sans-serif";
      ctx.fillText('의뢰인 '+Math.ceil(35-cl.age)+'초', 0, 26);
      ctx.restore();
    }
    // 떠돌이 상인
    for (const mc of merchants){
      ctx.save();
      drawShadow(mc.x, mc.y+15, 11);
      drawHumanoid(mc.x, mc.y, { face: player.x>mc.x?1:-1, walk: performance.now()/140, gear:null, scale:1.1, ink:PAL.ink2 });
      ctx.translate(mc.x, mc.y);
      // 봇짐
      ctx.fillStyle = COLORS.chest;
      ctx.strokeStyle = '#8a6428';
      ctx.lineWidth = 1.4;
      ctx.beginPath(); ctx.arc(-9,-6,7,0,Math.PI*2); ctx.fill(); ctx.stroke();
      // 골드 코인 표시
      const cb = Math.sin(performance.now()/250)*3;
      ctx.fillStyle = COLORS.gold;
      ctx.beginPath(); ctx.moveTo(0,-30+cb); ctx.lineTo(5,-24+cb); ctx.lineTo(0,-18+cb); ctx.lineTo(-5,-24+cb); ctx.closePath(); ctx.fill();
      ctx.fillStyle = PAL.ink;
      ctx.font = "600 9px 'IBM Plex Sans KR', sans-serif";
      ctx.textAlign = 'center';
      ctx.fillText('상인 '+Math.ceil(40-mc.age)+'초', 0, 26);
      ctx.restore();
    }
    // 시련의 제단
    for (const al of altars){
      ctx.save();
      ctx.translate(al.x, al.y);
      const pulse2 = 0.6 + Math.sin(performance.now()/220)*0.4;
      ctx.strokeStyle = PAL.ink;
      ctx.globalAlpha = pulse2;
      ctx.setLineDash([5,5]);
      ctx.lineWidth = 1.6;
      ctx.beginPath(); ctx.arc(0,0,al.r+8,0,Math.PI*2); ctx.stroke();
      ctx.setLineDash([]);
      ctx.globalAlpha = 1;
      // 제단 기둥 + 불꽃
      ctx.fillStyle = PAL.ink2;
      ctx.beginPath();
      ctx.moveTo(-10,14); ctx.lineTo(-6,-8); ctx.lineTo(6,-8); ctx.lineTo(10,14);
      ctx.closePath(); ctx.fill();
      ctx.fillRect(-12,12,24,4);
      const ff2 = Math.sin(performance.now()/90)*2;
      ctx.fillStyle = COLORS.fire;
      ctx.beginPath();
      ctx.moveTo(-5,-8); ctx.quadraticCurveTo(-3,-16-ff2,0,-20-ff2);
      ctx.quadraticCurveTo(3,-14+ff2,5,-8);
      ctx.closePath(); ctx.fill();
      ctx.fillStyle = PAL.ink;
      ctx.font = "600 9px 'IBM Plex Sans KR', sans-serif";
      ctx.textAlign = 'center';
      ctx.fillText('시련', 0, 28);
      ctx.restore();
    }
    // 보스 지뢰 (위험 = 빨강)
    for (const m of bossMines){
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.fillStyle = m.armT>0 ? PAL.mid : COLORS.danger;
      ctx.beginPath(); ctx.arc(0,0,m.r*0.8,0,Math.PI*2); ctx.fill();
      if (m.armT<=0 && Math.floor(performance.now()/300)%2===0){
        ctx.fillStyle = '#fff0ee';
        ctx.beginPath(); ctx.arc(0,0,2,0,Math.PI*2); ctx.fill();
      }
      ctx.restore();
    }
    // 아군 지뢰 (폭발 테크 = 주황)
    for (const m of fmines){
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.strokeStyle = COLORS.boom;
      ctx.lineWidth = 1.4;
      ctx.beginPath(); ctx.arc(0,0,7,0,Math.PI*2); ctx.stroke();
      ctx.fillStyle = m.armT>0 ? PAL.soft : COLORS.boom;
      ctx.beginPath(); ctx.arc(0,0,3.4,0,Math.PI*2); ctx.fill();
      ctx.restore();
    }
  }
  //  ═══════════════════════════════════════════════════════════════════════════
  //  🔴 v6.198 **도트 이펙트 툴킷** — 사용자 지시: 캐릭터 다음은 이펙트.
  //   캐릭터에서 배운 것이 이펙트에도 그대로 적용된다:
  //    ① **블록으로 찍는다** — 부드러운 호·그라디언트는 벡터로 읽힌다. 정수 격자에 스냅한 사각형만 쓴다
  //    ② **시간을 3~4단으로 끊는다** — 알파를 매끄럽게 줄이면 '사라지는 벡터'다.
  //       도트 이펙트가 '움직이는 그림'으로 읽히는 이유는 **프레임이 뚝뚝 끊기기** 때문이다
  //    ③ **3톤 램프** — 심(밝게) / 본체(속성색) / 가장자리(차갑고 어둡게). 색조 이동은 캐릭터와 같은 규칙
  //   ⚠ 블록 크기는 월드 도트(2px)보다 **한 단 크게**(3px) — 같으면 배경 격자에 묻힌다
  const FXPX = 3;
  function fxBlock(x, y, c, s){
    const k = s || FXPX;
    ctx.fillStyle = c;
    ctx.fillRect(Math.round(x/k)*k, Math.round(y/k)*k, k, k);
  }
  //  3톤 램프 — 그림자는 차갑게(캐릭터 팔레트와 같은 규칙)
  const FX_RAMP_CACHE = {};
  function fxRamp(col){
    if (FX_RAMP_CACHE[col]) return FX_RAMP_CACHE[col];
    const r = [ mixHex(col,'#fffbe8',0.72), col, mixHex(col,'#241a45',0.42) ];
    FX_RAMP_CACHE[col] = r;
    return r;
  }
  //  진행도를 N단으로 끊는다 — 이펙트가 '벡터처럼 스르륵'이 아니라 '도트처럼 뚝뚝' 가게 하는 핵심
  function fxStep(t, n){ return Math.min(n-1, Math.floor(t*n)); }
  //  ═══════════════════════════════════════════════════════════════════════════
  //  🔴 v6.199 **벡터 번개** — 사용자: *"벡터를 이정도로하게해주는건 어렵나?"* (검정 배경 청록 번개 레퍼런스)
  //   어렵지 않다. 저 그림의 힘은 손맛이 아니라 **네 가지 기법**이고 전부 코드로 재현된다:
  //    ① **중심선 변위(midpoint displacement)** — 곡선이 아니라 **각진 꺾임**이어야 번개다
  //    ② **4겹 스트로크** — 어두운 윤곽 / 발광 헤일로 / 본체 / **흰 심(가장 얇게)**.
  //       레퍼런스의 '빛나는' 느낌은 전부 **흰 심 + 채도 높은 헤일로**의 대비에서 나온다
  //    ③ **끝으로 갈수록 얇아진다** — 균일 굵기면 전선이지 번개가 아니다
  //    ④ **파편(shard)** — 본선에서 튀어나가는 작은 각진 조각. 이게 없으면 그냥 선이다
  //
  //   ⚠⚠ **레퍼런스는 완전한 검정 위다.** 이 게임은 13맵 중 **7맵이 밝은 배경**이고,
  //    가산합성 발광은 밝은 배경에서 아무 일도 안 한다(흰색보다 밝아질 수 없다).
  //    ⇒ 밝은 맵에서는 **어두운 윤곽**이 형태를 잡고, 어두운 맵에서만 헤일로를 가산으로 얹는다.
  //    같은 코드가 양쪽에서 다르게 읽히도록 짠다.
  //   📌 캐릭터는 도트, 이펙트는 매끈한 발광 — 이 조합은 흔하고 정당하다(데드셀즈·하이퍼라이트 계열).
  //    v6.198의 '이펙트도 도트로'는 **내 판단이었지 지시가 아니었다**.
  function boltPath(x0, y0, x1, y1, seed, amp, depth){
    let pts = [[x0,y0],[x1,y1]];
    let s = seed;
    const rnd = ()=>{ s = (s*1664525 + 1013904223) & 0x7fffffff; return s/0x7fffffff; };
    for (let d=0; d<(depth||5); d++){
      const out = [pts[0]];
      const a = amp / (d+1);
      for (let i=0;i<pts.length-1;i++){
        const A = pts[i], B = pts[i+1];
        const mx = (A[0]+B[0])/2, my = (A[1]+B[1])/2;
        const dx = B[0]-A[0], dy = B[1]-A[1], L = Math.hypot(dx,dy)||1;
        const off = (rnd()-0.5)*a;
        out.push([mx - dy/L*off, my + dx/L*off]);
        out.push(B);
      }
      pts = out;
    }
    return pts;
  }
  //  🔴 v6.200 **질감 재작업** — 사용자: *"뭔가 질감이 다른데? 내가준거랑??"*
  //   맞다. v6.199는 **균일 굵기 스트로크 + 흰 심**이라 '네온 튜브'였다. 레퍼런스는 기법이 다르다:
  //    ① 선이 아니라 **리본(닫힌 폴리곤)** 이다 — 마디마다 **부풀었다 잘록해지고** 끝이 뾰족하다
  //    ② **안쪽이 비어 있다** — 어두운 속 + **밝은 테두리**. 그래서 '그려진 것'처럼 보인다
  //    ③ 흰색은 길 전체가 아니라 **몇 군데에만** 얹힌다
  //   ⇒ 스트로크를 버리고 **폭 프로파일을 가진 리본 폴리곤**으로 간다.
  //  ── 중심선 + 정점별 폭 → 닫힌 리본 폴리곤
  function boltRibbon(pts, ws){
    const A=[], B=[];
    for (let i=0;i<pts.length;i++){
      const p0 = pts[Math.max(0,i-1)], p1 = pts[Math.min(pts.length-1,i+1)];
      const dx=p1[0]-p0[0], dy=p1[1]-p0[1], d=Math.hypot(dx,dy)||1;
      const nx=-dy/d, ny=dx/d, w=ws[i];
      A.push([pts[i][0]+nx*w, pts[i][1]+ny*w]);
      B.push([pts[i][0]-nx*w, pts[i][1]-ny*w]);
    }
    return A.concat(B.reverse());
  }
  //  ⚠ 폭이 매끄럽게 줄기만 하면 다시 튜브다 — **마디마다 부풀고 잘록해져야** 손으로 그린 리본이 된다
  function boltWidths(pts, base, seed){
    const n = pts.length-1, ws = [];
    let s = seed|0;
    const rnd = ()=>{ s = (s*1664525 + 1013904223) & 0x7fffffff; return s/0x7fffffff; };
    for (let i=0;i<=n;i++){
      const t = i/n;
      const taper = Math.pow(1-t, 0.55);                 // 끝으로 갈수록 뾰족하게
      const swell = 0.14 + 1.45*Math.pow(rnd(), 0.75);   // ⚠ 요동 폭이 작으면 다시 튜브다    // 마디별 굵기 요동 (이게 질감이다)
      ws.push(Math.max(0.35, base * taper * swell));
    }
    ws[n] = 0.2;                                         // 끝점은 한 점으로 — 뾰족한 촉
    return ws;
  }
  function polyPath(poly){
    ctx.beginPath();
    ctx.moveTo(poly[0][0], poly[0][1]);
    for (let i=1;i<poly.length;i++) ctx.lineTo(poly[i][0], poly[i][1]);
    ctx.closePath();
  }
  //  🔴 v6.207 중점 스무딩 — 레퍼런스(전문 슬래시 스프라이트)는 모서리가 **하나도** 없다.
  //   각 꼭짓점을 지나지 않고 중점끼리 이차 곡선으로 이어 다각형 모서리를 죽인다.
  function polyPathS(poly){
    const n = poly.length;
    ctx.beginPath();
    ctx.moveTo((poly[0][0]+poly[n-1][0])/2, (poly[0][1]+poly[n-1][1])/2);
    for (let i=0;i<n;i++){ const p=poly[i], q=poly[(i+1)%n];
      ctx.quadraticCurveTo(p[0],p[1],(p[0]+q[0])/2,(p[1]+q[1])/2); }
    ctx.closePath();
  }
  //  ⚠ 굵기가 균일하면 전선이다 — 구간마다 굵기를 줄여 가며 따로 긋는다
  function boltStroke(pts, col, w, cap){
    ctx.lineCap = cap || 'round'; ctx.lineJoin = 'round';
    ctx.strokeStyle = col;
    const n = pts.length-1;
    for (let i=0;i<n;i++){
      ctx.lineWidth = Math.max(0.6, w * (1 - i/n*0.72));
      ctx.beginPath(); ctx.moveTo(pts[i][0], pts[i][1]); ctx.lineTo(pts[i+1][0], pts[i+1][1]); ctx.stroke();
    }
  }
  function drawBolt(pts, col, w, dark, seed){
    const ws = boltWidths(pts, w*2.5, (seed|0) || 7);
    const poly = boltRibbon(pts, ws);
    ctx.save();
    ctx.lineJoin = 'round'; ctx.lineCap = 'round';
    //  ① 헤일로 — 어두운 맵에서만 가산. 밝은 맵에서는 흰색을 못 넘으므로 의미가 없다
    if (dark){
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = 0.22; ctx.strokeStyle = col; ctx.lineWidth = w*3.4;
      polyPath(poly); ctx.stroke();
      ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
    }
    //  ② 속 — **비운다**. 어두운 맵은 검정, 밝은 맵은 잉크.
    //   이 '윤곽선으로 딴 리본' 이 레퍼런스 질감의 핵심이다 — 꽉 찬 스트로크는 네온 튜브가 된다
    ctx.fillStyle = dark ? 'rgba(6,8,14,0.92)' : mixHex(col, '#14121e', 0.80);
    polyPath(poly); ctx.fill();
    //  ③ 테두리 — 밝은 색으로 리본을 딴다
    ctx.strokeStyle = col; ctx.lineWidth = Math.max(1.4, w*0.62);
    polyPath(poly); ctx.stroke();
    //  ④ 흰 하이라이트 — **길 전체가 아니라 몇 마디에만**. 전체에 깔면 다시 튜브가 된다
    ctx.strokeStyle = dark ? '#ffffff' : mixHex(col,'#ffffff',0.9);
    ctx.lineWidth = Math.max(1, w*0.34);
    if (dark) ctx.globalCompositeOperation = 'lighter';
    for (let i=0;i<pts.length-1;i++){
      if ((i + (seed|0)) % 2) continue;
      ctx.beginPath(); ctx.moveTo(pts[i][0],pts[i][1]); ctx.lineTo(pts[i+1][0],pts[i+1][1]); ctx.stroke();
    }
    ctx.restore();
  }
  //  파편 — 본선에서 튀어나가는 각진 조각. 이게 없으면 그냥 구불구불한 선이다
  function drawBoltShards(pts, col, w, dark, seed){
    let s = seed|0;
    const rnd = ()=>{ s = (s*1103515245 + 12345) & 0x7fffffff; return s/0x7fffffff; };
    ctx.save();
    if (dark) ctx.globalCompositeOperation = 'lighter';
    for (let i=2;i<pts.length-2;i+=3){
      if (rnd() > 0.45) continue;
      const A = pts[i], B = pts[i+1];
      const dx = B[0]-A[0], dy = B[1]-A[1], L = Math.hypot(dx,dy)||1;
      const nx = -dy/L, ny = dx/L, sg = rnd()<0.5?-1:1;
      const len = 6 + rnd()*16;
      const tipX = A[0] + nx*sg*len + dx*0.4, tipY = A[1] + ny*sg*len + dy*0.4;
      if (!dark){ ctx.fillStyle = 'rgba(14,12,22,0.85)';
        ctx.beginPath(); ctx.moveTo(A[0]-nx*sg*2.6, A[1]-ny*sg*2.6);
        ctx.lineTo(tipX, tipY); ctx.lineTo(A[0]+dx*0.9+nx*sg*2.6, A[1]+dy*0.9+ny*sg*2.6);
        ctx.closePath(); ctx.fill(); }
      ctx.fillStyle = col;
      ctx.beginPath(); ctx.moveTo(A[0]-nx*sg*1.4, A[1]-ny*sg*1.4);
      ctx.lineTo(tipX, tipY); ctx.lineTo(A[0]+dx*0.9+nx*sg*1.4, A[1]+dy*0.9+ny*sg*1.4);
      ctx.closePath(); ctx.fill();
      if (rnd()<0.5){ ctx.fillStyle = dark ? '#ffffff' : mixHex(col,'#ffffff',0.8);
        ctx.beginPath(); ctx.arc(tipX, tipY, 1.6+rnd()*1.8, 0, 6.283); ctx.fill(); }
    }
    ctx.restore();
  }
  //  ═══════════════════════════════════════════════════════════════════════════
  //  🔴 v6.201 **직업 고유 이펙트 37종** — 사용자: *"좋다 그런느낌으로 모든 직업을 다만들어봐"*
  //   v6.200의 리본 기법(윤곽선으로 딴 면 · 폭 요동 · 뾰족한 촉)을 **전 직업**에 얹는다.
  //   ⚠ 아키타입 돌려쓰기 금지 — v6.179 교훈("나눠 주는 것은 고유가 아니다").
  //    프리미티브는 공유하되 **형태·수·각도·조합이 전부 다르다**.
  //   ⚠ 색은 직업 악센트(`CLASS_COLORS`)를 쓴다 — 37장 초상화와 같은 색이라 "그 직업"으로 읽힌다.
  //   ⚠ 밝은 맵 7개에서는 가산 발광이 안 먹는다 → `dark` 분기는 프리미티브가 알아서 처리한다.
  //  ── 🔴 v6.201 프리미티브 — **라테일식 발광 덩어리**.
  //   사용자: *"뭔가 라테일의 이펙트 느낌이 가장좋긴한데"*
  //   ⚠ v6.200의 번개는 **속을 비운 선화**였다. 라테일 계열은 정반대다:
  //    ① **채운 덩어리** — 속이 꽉 찬 큰 면 ② **흰 심 → 채도색 → 번짐**의 3단 램프
  //    ③ **커지면서 흐려진다**(진행도로 확대+페이드) ④ 캐릭터보다 **크다**
  //   ⇒ 리본 폴리곤(폭 요동·뾰족한 촉)은 형태감으로 남기되 **속을 채우고 발광을 얹는다**.
  //   ⚠ 밝은 맵 7개에서는 가산 번짐이 안 먹는다 → 어두운 테두리로 형태를 분리한다.
  let LA_T = 0;                     // 현재 이펙트 진행도(0→1) — 프리미티브가 공유한다
  //  🔴 v6.202 **다중 색 램프** — 라테일은 한 이펙트 안에서 색이 흐른다(흰→하늘→남색).
  //   v6.201은 단색 + 흰 심이라 '색이 하나인 네온'이었다. 폭 방향으로 **4단**을 겹쳐 흐름을 만든다:
  //   바깥(깊은 색·넓게) → 본체(직업색) → 안쪽(밝게) → 심(흰색·가장 얇게).
  //   ⚠ 깊은 색은 검정을 섞는 게 아니라 **차가운 쪽(남보라)으로 민다** — 캐릭터 팔레트와 같은 색조 이동 규칙.
  const LA_RAMP = {};
  //  🔴 v6.211 **이펙트 전용 색 부스트** — 사용자: "색감이나 이런것도".
  //   CLASS_COLORS는 흑백 월드용 탁한 악센트(#8a6a4f류)라 어떤 램프를 얹어도 칙칙했다.
  //   이펙트에서만 채도·명도를 끌어올린다(HSL: s ×1.5+0.1, l → 0.52~0.62). 월드 악센트는 그대로.
  function fxVivid(col){
    const R0=parseInt(col.slice(1,3),16)/255, G0=parseInt(col.slice(3,5),16)/255, B0=parseInt(col.slice(5,7),16)/255;
    const mx=Math.max(R0,G0,B0), mn=Math.min(R0,G0,B0); let h=0, l=(mx+mn)/2;
    let sat = mx===mn ? 0 : (l>0.5 ? (mx-mn)/(2-mx-mn) : (mx-mn)/(mx+mn));
    if (mx!==mn){
      if (mx===R0) h=((G0-B0)/(mx-mn)+(G0<B0?6:0))/6;
      else if (mx===G0) h=((B0-R0)/(mx-mn)+2)/6;
      else h=((R0-G0)/(mx-mn)+4)/6;
    }
    sat = Math.min(1, sat*1.5+0.10); l = Math.max(0.52, Math.min(0.62, l+0.08));
    const q = l<0.5 ? l*(1+sat) : l+sat-l*sat, p = 2*l-q;
    const f=(tc)=>{ let u=tc<0?tc+1:tc>1?tc-1:tc;
      if (u<1/6) return p+(q-p)*6*u; if (u<0.5) return q; if (u<2/3) return p+(q-p)*(2/3-u)*6; return p; };
    const to=(v)=>('0'+Math.round(v*255).toString(16)).slice(-2);
    return '#'+to(f(h+1/3))+to(f(h))+to(f(h-1/3));
  }
  function laRamp(col){
    if (LA_RAMP[col]) return LA_RAMP[col];
    const v = fxVivid(col);
    //  v6.207 채도 유지 — 몸통은 끝까지 진하다. 흰 기운은 뜨거운 날(core) 한 줄뿐.
    const r = { deep: mixHex(v, '#241a6a', 0.55), mid: v,
                lit: mixHex(v, '#fff2c8', 0.30), core: mixHex(v, '#ffffff', 0.92) };
    LA_RAMP[col] = r; return r;
  }
  //  각을 살려야 하는 도형(글리치 조각·차트 캔들·카드)은 중점 스무딩을 끈다
  let LA_SHARP = false;
  function laDraw(pts, w, col, dark, seed){
    const t = LA_T;
    //  🔴 v6.207 **전문 슬래시 문법으로 전면 교체** — 레퍼런스 이미지(상용 슬래시 스프라이트 팩)를 직접 보고 뜯었다:
    //   ① 외곽선이 **없다** — 헤일로·어두운 윤곽을 두르면 스티커가 된다(v6.206까지의 '초등학생 그림'의 정체)
    //   ② 색은 도형 **안에서 흐른다** — 꼬리(깊은 색) → 몸(본색) → 머리(밝음)의 길이 방향 그라디언트 한 번
    //   ③ 흰 값은 **한쪽 날에만** — 스파인을 한쪽으로 밀어낸 얇은 리본. 중앙선 전체에 깔면 네온 튜브다
    //   ④ 모서리 금지 — 중점 스무딩(polyPathS)
    //  다단(v6.204)은 유지: 터짐 → 퍼짐 → 잔몸(외곽선 대신 몸이 옅게 남는다) → 걷힘.
    //  🔴 v6.211 **늘어나지 않는다** — 사용자: "그냥 길쭉하게 늘어나는 느낌".
    //   레퍼런스 스프라이트는 거의 안 커진다: 1프레임에 완성 크기로 터지듯 나타나고(0.86→1.04),
    //   이후는 알파·단계가 처리한다. 계속 커지는 건(0.6→1.24) 고무줄이다.
    let sc, fade, coreA;
    if (t < 0.10){ const u = t/0.10; const ov=u*(2-u); sc = 0.86+0.18*ov; fade = Math.min(1,u*1.5); coreA = Math.min(1, u*1.8); }
    else if (t < 0.5){ const u = (t-0.10)/0.40; sc = 1.04+0.05*u; fade = 1-0.12*u; coreA = 1-0.4*u; }
    else if (t < 0.8){ const u = (t-0.5)/0.3; sc = 1.09+0.04*u; fade = 0.88*(1-u)*(1-u)+0.05; coreA = 0.6*(1-u); }
    else { const u = (t-0.8)/0.2; sc = 1.13; fade = 0.05*(1-u); coreA = 0; }
    const R = laRamp(col);
    //  ⚠ v6.201: 라테일은 이펙트가 캐릭터를 덮는다 — 폭·확대 유지.
    //  v6.206: w가 배열이면 명시적 폭(형태가 정한다), 숫자면 난수 요동(유기 리본).
    const ws = Array.isArray(w) ? w.map(v=>Math.max(0.2, v*3.1*sc))
                                : boltWidths(pts, w*3.1*sc, seed);
    //  스파인 노멀 — 뜨거운 날을 한쪽으로 밀 때 쓴다
    const N=[]; for(let i=0;i<pts.length;i++){ const p0=pts[Math.max(0,i-1)], p1=pts[Math.min(pts.length-1,i+1)];
      const dx=p1[0]-p0[0], dy=p1[1]-p0[1], dd=Math.hypot(dx,dy)||1; N.push([-dy/dd, dx/dd]); }
    const poly = boltRibbon(pts, ws);
    const A=pts[0], B=pts[pts.length-1];
    const span = Math.hypot(B[0]-A[0], B[1]-A[1]);
    ctx.save(); ctx.lineJoin="round"; ctx.lineCap="round";
    if (dark) ctx.globalCompositeOperation = "lighter";
    //  ① 몸통 — 꼬리(깊음)→머리(밝음) 그라디언트 fill 한 번. 고리처럼 시작=끝이면 평색.
    if (span > 6){
      const g = ctx.createLinearGradient(A[0],A[1],B[0],B[1]);
      g.addColorStop(0, R.deep); g.addColorStop(0.55, R.mid); g.addColorStop(1, R.lit);
      ctx.fillStyle = g;
    } else ctx.fillStyle = R.mid;
    ctx.globalAlpha = 0.92*fade;
    (LA_SHARP ? polyPath : polyPathS)(poly); ctx.fill();
    //  ② 뜨거운 날 — 스파인을 노멀 방향으로 민 얇은 리본. 머리로 갈수록 희다.
    if (coreA > 0.02){
      const sp = pts.map((p,i)=>[p[0]+N[i][0]*ws[i]*0.40, p[1]+N[i][1]*ws[i]*0.40]);
      const hot = boltRibbon(sp, ws.map(v=>Math.max(0.15, v*0.30)));
      if (span > 6){
        const g2 = ctx.createLinearGradient(A[0],A[1],B[0],B[1]);
        g2.addColorStop(0, 'rgba(255,255,255,0)'); g2.addColorStop(0.45, R.lit);
        g2.addColorStop(1, dark ? '#ffffff' : R.core);
        ctx.fillStyle = g2;
      } else ctx.fillStyle = dark ? '#ffffff' : R.core;
      ctx.globalAlpha = coreA*0.95;
      (LA_SHARP ? polyPath : polyPathS)(hot); ctx.fill();
    }
    ctx.restore();
    //  v6.213 백열 헤드 — 경로 머리(끝점)에 블룸. 에너지가 한 점에서 탄다.
    if (coreA > 0.3 && span > 14){
      const hw = Array.isArray(w) ? w[w.length-1]+w[Math.max(0,w.length-2)] : w;
      laBloom(B[0], B[1], Math.max(7, hw*2.6), col, dark, coreA*0.8);
    }
  }
  //  🔴 v6.213 **백열 블룸** — 스톡 이펙트 미리보기 분석: 모든 프로 이펙트는 흰 코어 둘레에
  //   **부드러운 방사형 글로우**가 있다(가산합성만으로는 안 나온다). 헤드·글린트·아이콘 심장에 깐다.
  function laBloom(x,y,r,col,dark,al){
    if (r < 2) return;
    const R2 = laRamp(col);
    ctx.save(); if (dark) ctx.globalCompositeOperation = "lighter";
    const g = ctx.createRadialGradient(x,y,0,x,y,r);
    g.addColorStop(0, "rgba(255,255,255,0.85)");
    g.addColorStop(0.28, R2.mid + "");
    g.addColorStop(1, "rgba(0,0,0,0)");
    //  ⚠ 밝은 맵에서 투명 종점이 검정을 섞으면 지저분 — source-over에선 알파를 크게 낮춘다
    ctx.globalAlpha = (dark ? 0.85 : 0.30) * (al===undefined ? 1 : al);
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(x,y,r,0,6.283); ctx.fill();
    ctx.restore();
  }
  //  4각 반짝임 — 라테일 계열의 서명 같은 장식
  function laGlint(x,y,r,col,dark){
    const t=LA_T, fade=Math.max(0,1-t);
    laBloom(x, y, r*2.4, col, dark, fade);
    ctx.save(); if (dark) ctx.globalCompositeOperation="lighter";
    ctx.globalAlpha=fade; ctx.fillStyle = dark ? "#ffffff" : mixHex(col,"#ffffff",0.8);
    ctx.beginPath();
    ctx.moveTo(x,y-r); ctx.quadraticCurveTo(x+r*0.16,y-r*0.16, x+r,y);
    ctx.quadraticCurveTo(x+r*0.16,y+r*0.16, x,y+r);
    ctx.quadraticCurveTo(x-r*0.16,y+r*0.16, x-r,y);
    ctx.quadraticCurveTo(x-r*0.16,y-r*0.16, x,y-r);
    ctx.fill(); ctx.restore();
  }
  function rbPts(fn, n){ const p=[]; for(let i=0;i<=n;i++) p.push(fn(i/n)); return p; }
  function rbArc(x,y,r,a0,a1,w,col,dark,seed,wob){
    const pts = rbPts(t=>{ const a=a0+(a1-a0)*t, rr=r*(1+(wob||0)*Math.sin(t*9+seed));
      return [x+Math.cos(a)*rr, y+Math.sin(a)*rr]; }, 14);
    laDraw(pts, w, col, dark, seed);
  }
  function rbLine(x,y,a,len,w,col,dark,seed,jag){
    const pts = rbPts(t=>{ const j=(jag||0)*Math.sin(t*11+seed)*len*0.06;
      return [x+Math.cos(a)*len*t - Math.sin(a)*j, y+Math.sin(a)*len*t + Math.cos(a)*j]; }, 8);
    laDraw(pts, w, col, dark, seed);
  }
  function rbBurst(x,y,r0,r1,n,w,col,dark,seed,spread,base){
    for(let k=0;k<n;k++){
      const a = (base||0) + (spread||6.283)*(k/n - (spread?0.5:0)) + seed*0.013;
      rbLine(x+Math.cos(a)*r0, y+Math.sin(a)*r0, a, r1-r0, w, col, dark, seed+k*37, 0.4);
    }
  }
  function rbRing(x,y,r,w,col,dark,seed,lobe){
    const pts = rbPts(t=>{ const a=t*6.283, rr=r*(1+(lobe||0.12)*Math.sin(a*5+seed));
      return [x+Math.cos(a)*rr, y+Math.sin(a)*rr]; }, 26);
    laDraw(pts, w, col, dark, seed);
  }
  function rbCrescent(x,y,a,len,w,col,dark,seed){
    const pts = rbPts(t=>{ const th=a-0.9+1.8*t;
      return [x+Math.cos(th)*len, y+Math.sin(th)*len]; }, 8);
    laDraw(pts, w, col, dark, seed);
  }
  function rbBolt(x,y,a,len,w,col,dark,seed,br){
    for(let k=0;k<(br||1);k++){
      const sp=a+(k-((br||1)-1)/2)*0.34;
      const pts=boltPath(x,y,x+Math.cos(sp)*len,y+Math.sin(sp)*len,seed+k*977,len*0.46,3);
      //  ⚠⚠ 여기서 인자 순서를 틀렸었다 — `drawBolt(pts, col, w, …)`와 `laDraw(pts, w, col, …)`는
      //   앞 두 인자의 순서가 반대다. 어두운 맵은 흰색을 상수로 써서 `mixHex`를 안 타기 때문에
      //   **조용히 넘어갔고 밝은 맵에서만 터졌다**(`h.slice is not a function`).
      //   게다가 한 직업이 던지면 `ctx.save` 스택이 어긋나 **그 뒤 직업 전부가 안 보였다**.
      //   📌 비슷한 프리미티브를 둘 만들 때는 **인자 순서를 반드시 같게** 할 것.
      laDraw(pts, k===0?w:w*0.62, col, dark, seed+k*7);
    }
  }
  //  ── 🔴 v6.206 깎은 프리미티브 — 레퍼런스 조사(모바일 액션 VFX 공통 원칙) 세 가지를 코드로:
  //   ① 형태 언어가 1순위(난수 요동이 아니라 실루엣이 정체성을 말한다)
  //   ② 에너지는 한 점에 몬다(laDraw 심이 경로 끝으로 갈수록 밝다 — 위에서 처리)
  //   ③ 보조 요소(불똥·반짝임)가 한 방을 마무리한다
  //  칼날 — 🔴 v6.207 레퍼런스의 **쉼표(comma) 실루엣**: 두툼한 머리가 길고 가는 채찍 꼬리로 빠진다.
  //   대칭 초승달이 아니다. 꼬리→머리 순서로 그려 laDraw의 밝은 끝(그라디언트 머리)이 '베는 쪽'에 온다.
  //   hook = 꼬리가 안으로 감기는 정도.
  function rbBlade(x,y,a,span,rad,w,col,dark,seed,hook){
    const h = hook===undefined ? 0.22 : hook;
    const pts = rbPts(u=>{ const th = a + span*0.62 - span*u;
      const rr = rad*(1 - h*Math.pow(1-u, 1.6));
      return [x+Math.cos(th)*rr, y+Math.sin(th)*rr]; }, 16);
    const ws = pts.map((_,i)=>{ const u=i/(pts.length-1);
      return Math.max(0.15, w*(0.10 + 0.90*Math.pow(u, 1.35))); });
    ws[0] = 0.1;
    laDraw(pts, ws, col, dark, seed);
    //  에코 슬리버 — 본체 안쪽에 얇은 잔선 한 겹(레퍼런스의 이중 스트로크)
    const ep = rbPts(u=>{ const th = a + span*0.5 - span*0.86*u;
      const rr = rad*0.76*(1 - h*Math.pow(1-u, 1.6));
      return [x+Math.cos(th)*rr, y+Math.sin(th)*rr]; }, 10);
    const ews = ep.map((_,i)=>{ const u=i/(ep.length-1);
      return Math.max(0.1, w*0.30*(0.15 + 0.85*Math.pow(u, 1.3))); });
    laDraw(ep, ews, col, dark, seed+331);
  }
  //  바늘 — 밑동이 가늘고 끝 직전에 부풀었다가 한 점으로 꽂힌다(찌르기·창격).
  function rbNeedle(x,y,a,len,w,col,dark,seed){
    const pts = rbPts(u=>[x+Math.cos(a)*len*u, y+Math.sin(a)*len*u], 8);
    const ws = pts.map((_,i)=>{ const u=i/(pts.length-1);
      return Math.max(0.2, u<0.78 ? w*(0.30+0.58*u) : w*0.83*(1-u)/0.22); });
    laDraw(pts, ws, col, dark, seed);
  }
  //  화살촉·진격 표식 — 꼭짓점이 (x,y), a 방향을 가리킨다.
  function rbChev(x,y,a,size,w,col,dark,seed){
    const b1=a+2.55, b2=a-2.55;
    laDraw([[x+Math.cos(b1)*size,y+Math.sin(b1)*size],[x,y],[x+Math.cos(b2)*size,y+Math.sin(b2)*size]],
           [0.25,w,0.25], col, dark, seed);
  }
  //  별 — 표창(n=4)·다이아 룬(n=2)·플래시(n=4 겹침). 닫힌 별 외곽을 리본으로 두른다.
  function rbStar(x,y,rOut,rIn,n,w,col,dark,seed,rot){
    const pts=[];
    for(let k=0;k<=n*2;k++){ const a2=(rot||0)+k*(Math.PI/n); const rr=(k%2)?rIn:rOut;
      pts.push([x+Math.cos(a2)*rr, y+Math.sin(a2)*rr]); }
    laDraw(pts, pts.map(()=>w), col, dark, seed);
  }
  //  작은 구슬 — 위성·혼·음표 머리. (반지름보다 굵은 고리 = 채워진 구슬)
  function rbOrb(x,y,r2,col,dark,seed){ rbRing(x,y,Math.max(2,r2*0.6),Math.max(2.4,r2),col,dark,seed,0.05); }
  //  보조 불똥 — 궤적 둘레의 짧은 스침. 이게 있어야 '손으로 마무리한 한 방'이 된다.
  function laSparks(x,y,a,rad,n,col,dark,seed){
    let s2=(seed|0)||7; const rnd=()=>{ s2=(s2*1664525+1013904223)&0x7fffffff; return s2/0x7fffffff; };
    for(let k=0;k<n;k++){
      const sa=a+(rnd()-0.5)*1.7, rr=rad*(0.45+rnd()*0.75), ln=4+rnd()*7;
      const sx=x+Math.cos(sa)*rr, sy=y+Math.sin(sa)*rr;
      //  v6.211 선이 아니라 **물방울 파편** — 머리가 통통하고 꼬리가 한 점으로 죽는다(레퍼런스의 흩어지는 조각)
      laDraw([[sx,sy],[sx+Math.cos(sa)*ln*0.45, sy+Math.sin(sa)*ln*0.45],[sx+Math.cos(sa)*ln, sy+Math.sin(sa)*ln]],
             [0.4, 2.0, 0.12], col, dark, (seed|0)+k*97);
    }
  }
